-- Ichetucknee Springs State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'ichetucknee-springs-state-park',
    'Ichetucknee Springs State Park',
    'spring',
    'state',
    29.98389,
    -82.76194,
    'deep',
    true,
    'no',
    '8 a.m. to sundown, 365 days a year. Swimming (North Entrance): Head Spring closes 30 minutes before park closing; Blue Hole Spring and its trail close 1 hour before closing. Tubing (South Entrance): Dampier''s Landing closes 5 p.m., tube rentals end 4:30 p.m., everyone off the river by 6 p.m. Midpoint Launch closed for repairs.',
    '$6 per vehicle (2-8 people); $4 single-occupant vehicle or motorcycle; $2 pedestrians, cyclists and extra passengers. Tube rentals are extra through the concessionaire (about $10-$35).',
    false,
    null,
    '{"alcohol":"Prohibited on the river and anywhere inside the park.","tubing":"Year-round from Dampier''s Landing (South Entrance) only; the north section is closed to tubing. Tubes up to 60 inches, no glitter; stay on your flotation device; no swimming from tubes on the river.","pets":"Not allowed in the water, on trails to launches or swim areas, or in vessels. Trestle Point and Pine Ridge trails are pet-friendly.","life_jackets":"Allowed and rentable; pool noodles are fine in the springs but not on the river.","other":["Swim only at the Head Spring and Blue Hole - no swimming anywhere on the river.","No coolers, food, disposables, glass, speakers, tobacco or vapes, water guns, DPVs or large inflatables at swim areas or on the water (armbands OK).","Scuba at Blue Hole only, cavern or cave certified, two-diver minimum, done one hour before sunset."]}'::jsonb,
    '02322700',
    null,
    4.2,
    '{"gridId":"JAX","gridX":25,"gridY":45,"forecast":"https://api.weather.gov/gridpoints/JAX/25,45/forecast","forecastHourly":"https://api.weather.gov/gridpoints/JAX/25,45/forecast/hourly"}'::jsonb,
    'FLZ021',
    'FLC121',
    '10:00',
    true,
    'No lifeguard on duty - swim at your own risk. The spring water is about 72 F year-round, cold enough to tire swimmers quickly. Blue Hole is deep with a strong current and is for experienced swimmers only; the stairs can be slippery. The Blue Hole vent is a cave - diving is for cavern/cave-certified divers only.',
    'https://www.floridastateparks.org/parks-and-trails/ichetucknee-springs-state-park',
    '/photos/ichetucknee-springs-state-park.jpg',
    'Two entrances. North Entrance (8294 SW Elim Church Rd, Fort White) is for swimming at the Head Spring and Blue Hole - no tubing. South Entrance (12087 SW US Hwy 27) is for tubing from Dampier''s Landing - no swimming. Entry is first-come, first-served; online passes do not guarantee entry or skip the line. When the park is full it closes to everyone, including pass holders; do not park and wait on the roadside - citations are issued. Third-party reports: arrive before 10 a.m. on summer weekends.',
    null,
    'A crystal-clear, spring-fed river in north Florida where you can swim at the Head Spring and Blue Hole or float the river from the South Entrance. On hot weekends and holidays the parking areas fill early and the gates close until space opens up.'
)
