-- Ruth B. Kirby Gilchrist Blue Springs State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'gilchrist-blue-springs-state-park',
    'Ruth B. Kirby Gilchrist Blue Springs State Park',
    'spring',
    'state',
    29.82972,
    -82.6829,
    'deep',
    true,
    'unknown',
    '8 a.m. to sundown, 365 days a year.',
    '$6 per vehicle (2-8 people); $4 single-occupant vehicle; $2 pedestrians and cyclists. Camping $18 per night plus fees.',
    false,
    null,
    '{"alcohol":"Prohibited (Florida State Parks rule, F.A.C. 62D-2.014).","tubing":"Not offered; rentals and concessions are unavailable during renovations.","pets":"Not allowed in swimming areas or the water (state park rule).","life_jackets":"Allowed; not required.","other":["Snorkeling only in designated areas.","Registered campers may enter after the gate closes at capacity; day visitors may not."]}'::jsonb,
    null,
    '02322500',
    3.8,
    '{"gridId":"JAX","gridX":29,"gridY":39,"forecast":"https://api.weather.gov/gridpoints/JAX/29,39/forecast","forecastHourly":"https://api.weather.gov/gridpoints/JAX/29,39/forecast/hourly"}'::jsonb,
    'FLZ035',
    'FLC041',
    '10:30',
    false,
    'No lifeguard statement is published - assume no lifeguard on duty. Spring water is about 72 F year-round. The spring run is shallow and clear, but the Santa Fe River can back up into the springs and turn them dark after heavy rain.',
    'https://www.floridastateparks.org/parks-and-trails/ruth-b-kirby-gilchrist-blue-springs-state-park',
    '/photos/gilchrist-blue-springs-state-park.jpg',
    'Entrance at 7450 NE 60th St, High Springs (386-454-1369). No day-use reservations. On busy weekends the gate closes at capacity and does not reopen to day visitors until 8 a.m. the next day (visitor and county reports). Since Oct 29, 2025 there are no water activities while a new swim entrance, launch, bathrooms and larger campground are built - no reopening date yet.',
    null,
    'A group of clear springs on the Santa Fe River that became a state park in 2017, known for a wide, shallow run and easy snorkeling. The swimming area is closed for renovations until further notice; the picnic area and pavilion stay open.'
)
