-- Rainbow Springs State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'rainbow-springs-state-park',
    'Rainbow Springs State Park',
    'spring',
    'state',
    29.1025,
    -82.4375,
    'deep',
    true,
    'no',
    'Headsprings (swimming) entrance: 8 a.m. to sunset, 365 days a year, unless closed at capacity. Tubing entrance: Memorial Day-Labor Day daily 8 a.m.-4 p.m. (last tram 4:30 p.m.); weekends only in spring and September (call to confirm); closed Oct-Mar.',
    '$5 per vehicle (2-8 people); $4 single-occupant vehicle; $2 pedestrians and cyclists. Tube rental and shuttle fees are extra, and the shuttle fee applies even with your own tube. Annual passes are sold on weekdays and non-holidays only.',
    true,
    'https://reserve.floridastateparks.org/Web/#!park/54',
    '{"alcohol":"Prohibited (Florida State Parks rule, F.A.C. 62D-2.014).","tubing":"Not allowed at the headsprings. Tubing only from the separate Tubing Entrance (2-mile float, about 2 hours); tubers must be 5 or older, and ages 5-6 must wear a fastened life jacket.","pets":"Welcome in the campground; not permitted in swimming areas or buildings.","life_jackets":"Life preservers and noodles are allowed at the headsprings; required for tubers ages 5-6.","other":["No inflatables of any kind (rafts, tubes, balls) at the headsprings.","Stay inside the buoyed swim area; snorkeling only inside the buoys (dive-flag law applies elsewhere).","No disposable food or drink containers on the river (aquatic preserve).","Private vessels must be carried about 1,800 ft from parking to the launch."]}'::jsonb,
    '02313098',
    null,
    3.6,
    '{"gridId":"JAX","gridX":41,"gridY":8,"forecast":"https://api.weather.gov/gridpoints/JAX/41,8/forecast","forecastHourly":"https://api.weather.gov/gridpoints/JAX/41,8/forecast/hourly"}'::jsonb,
    'FLZ340',
    'FLC083',
    '09:30',
    false,
    'No lifeguard on duty - all swimmers do so at their own risk. The water is about 72 F year-round. The headsprings swim area is 10-18 feet deep with no shallow end, so weak swimmers should wear a life preserver and everyone must stay inside the buoys. Paths around the springs are steep and uneven in places.',
    'https://www.floridastateparks.org/parks-and-trails/rainbow-springs-state-park',
    '/photos/rainbow-springs-state-park.jpg',
    'Three entrances. Main/headsprings (swimming) entrance at 19158 SW 81st Place Rd, Dunnellon requires a day-use reservation for everyone, including annual passholders, pedestrians and cyclists. Tubing entrance at 10830 SW 180th Ave Rd (seasonal). Campground at 18185 SW 94th St. When the headsprings reach capacity the park closes to all visitors and vehicles may not wait in line in the park or on adjacent roads. Parking lot renovation Sep 9, 2026 - Feb 4, 2027: limited parking. Third-party reports: typically hits capacity 9-10 a.m. on summer weekends.',
    null,
    'A first-magnitude spring near Dunnellon with a deep, clear swimming basin surrounded by gardens and man-made waterfalls from its roadside-attraction days. Reservations are now required for the headsprings entrance, and on summer weekends it still reaches capacity early.'
)
