-- Blue Spring State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'blue-spring-state-park',
    'Blue Spring State Park',
    'spring',
    'state',
    28.94722,
    -81.33972,
    'deep',
    true,
    'unknown',
    '8 a.m. until sundown, 365 days a year. Swimming season is April 1 - November 14; the spring run is closed to swimming and all water activities November 15 - March 31 for manatees (reopening can be delayed if manatees linger).',
    '$6 per vehicle (2-8 people); $4 single-occupant vehicle; $2 pedestrians, cyclists and extra passengers. Entry fee is collected online with the day-use reservation. Tube rentals extra (Blue Springs Adventures). Camping $24 per night; cabins $95 per night.',
    true,
    'https://reserve.floridastateparks.org/Web/#!park/9',
    '{"alcohol":"Prohibited (Florida State Parks rule, F.A.C. 62D-2.014).","tubing":"Allowed in season; enter at the upper entry and float about 1/8 mile to the main swim dock. Inflatables over 72 inches are not allowed.","pets":"Pets - including service animals - are not allowed on the water.","life_jackets":"Allowed; not required.","other":["No coolers, food, glass, speakers, tobacco, water guns or DPVs on the water.","No climbing the spring banks; no paddling in the swim area 10 a.m.-5 p.m.","Swimming with or approaching manatees is prohibited; no swimming after hours.","Scuba only in designated areas; open-water and free divers may not carry lights or go below 60 ft; 32 divers at a time; two-diver minimum."]}'::jsonb,
    '02235500',
    null,
    0.3,
    '{"gridId":"MLB","gridX":26,"gridY":86,"forecast":"https://api.weather.gov/gridpoints/MLB/26,86/forecast","forecastHourly":"https://api.weather.gov/gridpoints/MLB/26,86/forecast/hourly"}'::jsonb,
    'FLZ041',
    'FLC127',
    '10:00',
    true,
    'No lifeguard statement is published - assume no lifeguard on duty. The water is about 72 F year-round. The spring boil is deep and leads into a cave system below 60 ft (certified divers only, no lights for open-water divers); the run has a steady current toward the St. Johns River. Manatees use the run in winter - never approach or swim with them.',
    'https://www.floridastateparks.org/parks-and-trails/blue-spring-state-park',
    '/photos/blue-spring-state-park.jpg',
    '2100 W French Ave, Orange City (386-775-3663). Day-use reservations required since Jul 15, 2026 for everyone except campers and boat-tour guests; news reports put the daily cap at about 232 vehicle and 50 pedestrian/bike slots (estimate). The park frequently reaches capacity and may close for several hours; pedestrians and cyclists are not admitted while it is closed. Third-party reports: closed by about 10 a.m. on summer weekends.',
    '{"open":"04-01","close":"11-14","note":"Manatee season Nov 15 - Mar 31: swimming and all water activities in the spring run are prohibited. Reopening may be delayed if manatees linger."}'::jsonb,
    'A first-magnitude spring on the St. Johns River south of DeLand, famous for wintering manatees and a clear quarter-mile spring run for swimming and tubing. Swimming is only open April 1 - November 14, and day-use reservations are required.'
)
