-- Wekiwa Springs State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'wekiwa-springs-state-park',
    'Wekiwa Springs State Park',
    'spring',
    'state',
    28.71222,
    -81.45979,
    'deep',
    true,
    'no',
    '8 a.m. to sunset, 365 days a year. The swimming area is open from 8 a.m. until 30 minutes before park closing. Spring bathrooms may close briefly for cleaning; concession 9 a.m.-5 p.m.',
    '$6 per vehicle (up to 8 people); $4 single-occupant vehicle; $2 pedestrians, cyclists and extra passengers. The entry fee is collected online when you make the day-use reservation (no extra reservation fee). Camping $24 per night plus fees.',
    true,
    'https://reserve.floridastateparks.org/Web/#!park/75',
    '{"alcohol":"Prohibited (stated on the park''s picnicking page and F.A.C. 62D-2.014).","tubing":"Not offered at the spring; individual-size flotation devices are allowed in the swimming area.","pets":"Allowed on a 6-foot hand-held leash on trails and in use areas; not allowed in the swimming area.","life_jackets":"Allowed; not required. Children and non-swimmers must be with an adult swimmer at all times.","other":["No diving or jumping - the spring is shallow.","No scuba, hookah or other tank-assisted breathing systems.","Swimming and snorkeling only in the spring - not in Wekiwa Springs Run, Rock Springs Run or the Wekiva River.","No grills, pop-up tents or canopies on the spring lawn."]}'::jsonb,
    '02234600',
    '02235000',
    12,
    '{"gridId":"MLB","gridX":22,"gridY":76,"forecast":"https://api.weather.gov/gridpoints/MLB/22,76/forecast","forecastHourly":"https://api.weather.gov/gridpoints/MLB/22,76/forecast/hourly"}'::jsonb,
    'FLZ045',
    'FLC095',
    '10:00',
    false,
    'No lifeguards on duty - swimmers and snorkelers do so at their own risk. The water is 72 F year-round. The swim area is shallow (under 1 ft to about 5 ft), so diving and jumping are banned; the spring vent drops into a small cavern and scuba is prohibited. Children and non-swimmers must stay with an adult swimmer. Black bears and alligators live in the park.',
    'https://www.floridastateparks.org/parks-and-trails/wekiwa-springs-state-park',
    '/photos/wekiwa-springs-state-park.jpg',
    '1800 Wekiwa Circle, Apopka (407-553-4348), off I-4 exit 94 about 20 minutes north of downtown Orlando. Day-use reservations are required for everyone, including annual passholders (since Sep 2, 2025); the daily number of reservations equals park capacity and same-day slots sell out on hot weekends and holidays. Ask the ranger station for a re-entry ticket if you leave. Campground construction may be under way (notice effective Jun 26, 2026).',
    null,
    'A large spring-fed swimming lagoon just north of Orlando, ringed by a grassy lawn for picnics and the start of the Wekiva River paddling trail. It is one of the few state-park springs with a swim lift and ramp into the water, and day-use entry now runs on reservations.'
)
