-- Madison Blue Spring State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'madison-blue-spring-state-park',
    'Madison Blue Spring State Park',
    'spring',
    'state',
    30.48049,
    -83.24431,
    'deep',
    true,
    'no',
    '8 a.m. to sunset, 365 days a year. Swimming hours are 8 a.m. to sunset; all dives must be completed one hour before sunset.',
    '$4-$5 per vehicle ($5 for 2-8 people, $4 single-occupant); $2 pedestrians, bicyclists and extra passengers. Pay with the QR code at the entrance (honor system). No tube rentals in the park.',
    false,
    null,
    '{"alcohol":"Prohibited in all areas of the park (stated on the official swimming and picnicking pages).","tubing":"Inflatable floats and tubes are allowed in the spring and the adjacent river - bring your own (no rentals). Tubes may not exceed 60 inches in more than one direction; no motorized equipment; no food, drink, pets, tobacco, alcohol or disposable items on the water.","pets":"Picnic areas only, on a 6-foot hand-held leash. Not permitted in the spring, the adjacent river or any building. Service animals are not allowed in the swimming areas (public bathing place).","life_jackets":"Allowed; not required. There is no lifeguard, so monitor inexperienced swimmers closely.","other":["No climbing on, walking on, or jumping or diving from the limestone rocks around the spring.","Fishing and tobacco are banned in and around the spring; river fishing only from 400 ft past the spring.","Scuba is for cave/cavern-certified divers only - no open-water or free diving; two-diver minimum; sign in at the boardwalk; no DPVs; dives done one hour before sunset.","Vessels are not allowed in the spring or spring run, and there is no river launch in the park."]}'::jsonb,
    '02319302',
    '02319394',
    9.9,
    '{"gridId":"TAE","gridX":123,"gridY":91,"forecast":"https://api.weather.gov/gridpoints/TAE/123,91/forecast","forecastHourly":"https://api.weather.gov/gridpoints/TAE/123,91/forecast/hourly"}'::jsonb,
    'FLZ019',
    'FLC079',
    '10:00',
    true,
    'No lifeguard on duty - swim at your own risk and watch inexperienced swimmers closely. The water averages 72 F year-round. The spring is about 82 ft wide and up to 25 ft deep, with wading areas under 5 ft. The vent opens into one of the largest cave systems in the area - cave/cavern-certified divers only. The Withlacoochee River can rise and darken the spring after heavy rain. Alligators sometimes visit the swim area.',
    'https://www.floridastateparks.org/parks-and-trails/madison-blue-spring-state-park',
    '/photos/madison-blue-spring-state-park.jpg',
    '8300 NE State Road 6, Lee (850-815-0869), between Lee and Jasper. No reservations; pay by QR code at the gate. Official notice: the park experiences frequent closures between 10 a.m. and 3 p.m. on weekends and holidays due to high visitation - it closes at capacity and may reopen later the same day. Do not park and wait on the roadside or in the entrance area; local law enforcement issues citations. Temporary restrooms only, no bathhouse or changing area. Large RVs and trailers are not recommended (limited turnaround space).',
    null,
    'A first-magnitude spring in a limestone basin on the west bank of the Withlacoochee River near Lee, once voted the best swimming hole in the country. On summer weekends it closes at capacity as early as 10 a.m., so plan an early start.'
)
