-- Lafayette Blue Springs State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'lafayette-blue-springs-state-park',
    'Lafayette Blue Springs State Park',
    'spring',
    'state',
    30.12573,
    -83.22717,
    'deep',
    true,
    'no',
    '8 a.m. to sundown, 365 days a year. Divers register at the north entrance ranger station and must finish one hour before sundown.',
    '$5 per vehicle (2-8 people); $4 single-occupant vehicle; $2 pedestrians, bicyclists and extra passengers. Honor box - correct change required. Cabins $100 per night plus fees; walk-in camping currently unavailable.',
    false,
    null,
    '{"alcohol":"Prohibited (Florida State Parks rule, F.A.C. 62D-2.014).","tubing":"Not offered and no rentals in the park. Suwannee River outfitters nearby (Suwannee River Rendezvous 386-294-2510, Camp Suwannee River Outfitters 386-647-6624) rent canoes.","pets":"Dogs on a 6-foot hand-held leash; not permitted in the springs, cabins or buildings; may not be left unattended more than 30 minutes.","life_jackets":"Allowed; not required.","other":["Fishing is prohibited in the swim areas.","Scuba is cave diving only (Blue Springs and Green Sink) for certified teams of two or more; open-water diving is prohibited; no DPVs; register and show certification at the north entrance ranger station.","Day use, the spring and the ranger station are at the north entrance; the boat ramp and cabins are at the south entrance."]}'::jsonb,
    '02319950',
    '02320000',
    6.1,
    '{"gridId":"TAE","gridX":125,"gridY":76,"forecast":"https://api.weather.gov/gridpoints/TAE/125,76/forecast","forecastHourly":"https://api.weather.gov/gridpoints/TAE/125,76/forecast/hourly"}'::jsonb,
    'FLZ029',
    'FLC067',
    null,
    true,
    'No lifeguard on duty - swim at your own risk. The spring is 72 F year-round. The vent leads into the Green Sink cave system (over 12,000 ft surveyed) - certified cave divers only. The Suwannee River floods roughly one year in five and can back dark water into the spring (a brown-out); the swim area closes when the river is high or clarity is poor. A natural limestone bridge crosses the spring run.',
    'https://www.floridastateparks.org/parks-and-trails/lafayette-blue-springs-state-park',
    '/photos/lafayette-blue-springs-state-park.jpg',
    'North (day-use and spring) entrance at 799 NW Blue Spring Rd, Mayo (386-294-3667); the south entrance has the boat ramp and cabins. Honor-box entry, no reservations, first-come, first-served. The park publishes no capacity-closure pattern, so no typical fill time is listed. Check river levels before driving out - swimming closes when the Suwannee floods the spring.',
    null,
    'A quiet first-magnitude spring on the Suwannee River near Mayo, crossed by a natural limestone bridge and shaded by moss-hung oaks, with stilt cabins above the river. It rarely fills, but the swim area closes whenever the river backs up into the spring.'
)
