-- Troy Spring State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'troy-spring-state-park',
    'Troy Spring State Park',
    'spring',
    'state',
    30.00607,
    -82.99738,
    'deep',
    true,
    'no',
    '8 a.m. to sundown, 365 days a year. All dives must be completed one hour before sundown.',
    '$5 per vehicle (up to 8 people); $4 single-occupant vehicle; $2 pedestrians, bicyclists and extra passengers. Honor box - correct change required.',
    false,
    null,
    '{"alcohol":"Prohibited (Florida State Parks rule, F.A.C. 62D-2.014).","tubing":"Not offered; no rentals or tube launch.","pets":"Dogs on a 6-foot hand-held leash; not permitted in the spring or buildings; may not be left unattended more than 30 minutes. Service animals are allowed in all areas.","life_jackets":"Allowed; not required.","other":["Fishing only from the river bank or river dock - never in the swim area.","Scuba is open-water only for certified divers: no solo diving, no lights, no DPVs; show your certification; dives done one hour before sunset.","The remains of the steamboat Madison in the spring run are protected - do not disturb them."]}'::jsonb,
    '02320250',
    '02320500',
    8.7,
    '{"gridId":"TAE","gridX":134,"gridY":72,"forecast":"https://api.weather.gov/gridpoints/TAE/134,72/forecast","forecastHourly":"https://api.weather.gov/gridpoints/TAE/134,72/forecast/hourly"}'::jsonb,
    'FLZ029',
    'FLC067',
    null,
    false,
    'No lifeguard on duty - swim at your own risk. The spring is 72 F year-round and drops to about 70 ft at the vent, with shallow areas in the spring run for children. The Suwannee River can brown out the spring after heavy rain; swimming is not allowed when the spring is browned out or the river rises over the lower dock platform (park guidance). The dock is reached by a long paved switchback ramp.',
    'https://www.floridastateparks.org/parks-and-trails/troy-spring-state-park',
    '/photos/troy-spring-state-park.jpg',
    '674 NE Troy Springs Rd, Branford (386-935-4835). Honor-box entry, no reservations. A small park that publishes no capacity-closure pattern, so no typical fill time is listed. Check the park page or call before driving out in wet weather - the spring closes to swimming when the Suwannee floods it.',
    null,
    'A 70-foot-deep first-magnitude spring on the Suwannee River near Branford, with the ribs of the Civil War steamboat Madison visible in the shallow spring run. A quiet alternative to the bigger springs, reached by a paved switchback ramp down to a dock.'
)
