-- Fanning Springs State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'fanning-springs-state-park',
    'Fanning Springs State Park',
    'spring',
    'state',
    29.58912,
    -82.93318,
    'deep',
    true,
    'unknown',
    '8 a.m. to sundown, 365 days a year. Divers must register three hours before sunset and finish one hour before sunset.',
    '$6 per vehicle (up to 8 people); $4 single-occupant vehicle; $2 pedestrians, bicyclists and extra passengers; $2 per person arriving by boat (honor box on the dock). Cabins $100 per night plus fees.',
    false,
    null,
    '{"alcohol":"Prohibited (Florida State Parks rule, F.A.C. 62D-2.014).","tubing":"No tube run or rentals. Individual floats and rafts are allowed in the swim area (max 5 x 5 ft round or 4 x 6 ft rectangle).","pets":"Dogs on a 6-foot leash; not permitted in the swimming areas, cabins or buildings.","life_jackets":"Allowed; not required.","other":["Fishing from the swimming dock is prohibited; no cast nets.","Open-water scuba in the designated swim area only: certified, register with staff, two-diver minimum, no lights; capacity 15 divers at a time and 30 per day.","Idle speed in the spring run - manatees use it in cooler months; stay 50 ft from manatees.","No outside firewood (emerald ash borer)."]}'::jsonb,
    '02323502',
    '02323500',
    0.3,
    '{"gridId":"TBW","gridX":46,"gridY":168,"forecast":"https://api.weather.gov/gridpoints/TBW/46,168/forecast","forecastHourly":"https://api.weather.gov/gridpoints/TBW/46,168/forecast/hourly"}'::jsonb,
    'FLZ239',
    'FLC075',
    null,
    false,
    'No lifeguard statement is published - assume no lifeguard on duty. The spring is 72 F year-round and only 18-21 ft at its deepest, with a shallow area for toddlers; wade in from the shore or dock. The Suwannee River is right beside the spring and backs dark water into it after heavy rain, which closes swimming. Manatees may be in the spring run in cooler months - keep 50 ft away. The floating dock is being improved (from Aug 20, 2026) and swimmers may be asked to exit at any time.',
    'https://www.floridastateparks.org/parks-and-trails/fanning-springs-state-park',
    '/photos/fanning-springs-state-park.jpg',
    '18020 NW Highway 19, Fanning Springs (352-463-3420), right off US 19/98 at the Suwannee River bridge; boaters can enter from the river ($2 per person). No reservations; first-come, first-served. The park publishes no capacity-closure pattern, so no typical fill time is listed. Effective Aug 20, 2026 the floating dock is under improvement - swimming and boating stay open but be prepared to exit when asked.',
    null,
    'A second-magnitude spring (first-magnitude until the 1990s) beside the Suwannee River in Fanning Springs, with a shallow blue-green basin, a cypress-swamp boardwalk and riverfront cabins. Easy in-and-out swimming from the shore or dock, though the river can darken the spring after rain.'
)
