-- Manatee Springs State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'manatee-springs-state-park',
    'Manatee Springs State Park',
    'spring',
    'state',
    29.48968,
    -82.97679,
    'deep',
    true,
    'unknown',
    '8 a.m. to sundown, 365 days a year. Divers must register at the office by 3 p.m. and be out of the water one hour before sunset.',
    '$6 per vehicle (2-8 people); $4 single-occupant vehicle or motorcycle; $2 pedestrians, bicyclists and extra passengers. Diving is free with admission. Camping $20 per night plus fees.',
    false,
    null,
    '{"alcohol":"Prohibited (Florida State Parks rule, F.A.C. 62D-2.014).","tubing":"Not offered; no tube run or rentals. Swimming is only in the main spring basin.","pets":"Dogs on a 6-foot leash; not permitted in buildings or the swim area, and banned from all boardwalks. Leashed pets may wade in the spring run at the canoe launch.","life_jackets":"Allowed; not required.","other":["Swimming and free diving only in the main spring - prohibited in Catfish Hotel, the spring run and at the end of the boardwalk.","Scuba: open-water in the main spring and Catfish Hotel; cavern at Catfish Hotel; full-cave certification for Friedman Sink. 18 open-water/cavern divers at a time; register by 3 p.m.","Keep 50 ft from manatees.","No bicycles on the boardwalk; no outside firewood; no EV charging in the park."]}'::jsonb,
    '02323566',
    '02323500',
    11.8,
    '{"gridId":"TBW","gridX":45,"gridY":163,"forecast":"https://api.weather.gov/gridpoints/TBW/45,163/forecast","forecastHourly":"https://api.weather.gov/gridpoints/TBW/45,163/forecast/hourly"}'::jsonb,
    'FLZ239',
    'FLC075',
    null,
    true,
    'No lifeguard statement is published - assume no lifeguard on duty. The spring is 72 F year-round. Use caution - the current in the spring is swift (official). The vent and the nearby Catfish Hotel sink lead into a cave system: cave-certified divers only, and Catfish Hotel is closed to swimming. Manatees gather in the spring run in cooler months - never approach them. The Suwannee River can flood back into the spring after heavy rain and close swimming.',
    'https://www.floridastateparks.org/parks-and-trails/manatee-springs-state-park',
    '/photos/manatee-springs-state-park.jpg',
    '11650 NW 115 St, Chiefland (352-493-6072), about 6 miles west of US 19. No day-use reservations; first-come, first-served. The park publishes no capacity-closure pattern, so no typical fill time is listed. Effective Jan 14, 2026 the waterfront restroom and dump station are closed and no EV charging is allowed. Boaters can tie up at the river dock and walk the 800-ft boardwalk to the spring.',
    null,
    'A first-magnitude spring near Chiefland that sends about 100 million gallons a day down a short run to the Suwannee River, with an 800-foot boardwalk through cypress forest. Manatees use the run in winter; swimmers stay in the main spring basin.'
)
