-- De Leon Springs State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'de-leon-springs-state-park',
    'De Leon Springs State Park',
    'spring',
    'state',
    29.13415,
    -81.36284,
    'deep',
    true,
    'no',
    '8 a.m. until sunset, 365 days a year. Swimming 8 a.m. until 30 minutes before sunset. Old Sugar Mill Pancake House 8 a.m.-4 p.m. daily; boat house, rentals and visitor center run 9 a.m.-6 p.m. during spring break (Mar 14-22) and summer (May 30-Aug 9).',
    '$6 per vehicle (2-8 people); $4 single-occupant vehicle or motorcycle; $2 pedestrians, bicyclists and extra passengers. Canoe/kayak/paddleboard rentals and the 50-minute boat tour are extra (Guest Services).',
    false,
    null,
    '{"alcohol":"Not permitted in any area of the park (stated on the official swimming and picnicking pages).","tubing":"Not offered. Individual floats and rafts are allowed in the swim area (max 5 x 5 ft round or 4 x 6 ft rectangle).","pets":"Hand-held 6-foot leash at all times; not allowed in the sunbathing/swimming area; may not be left unattended. Service animals are allowed in all areas.","life_jackets":"Allowed; not required. Children and non-swimmers must stay with an adult swimmer inside the roped-off areas.","other":["No swimming or snorkeling in Spring Garden Run (boats and alligators).","No recreational scuba - instructional diving only with a permitted instructor; no free-diving into the spring cave.","The swimming area closes when lightning is detected within 6 miles.","Artifacts in the spring are protected by state law; no metal detectors."]}'::jsonb,
    null,
    '02236000',
    14.1,
    '{"gridId":"MLB","gridX":24,"gridY":94,"forecast":"https://api.weather.gov/gridpoints/MLB/24,94/forecast","forecastHourly":"https://api.weather.gov/gridpoints/MLB/24,94/forecast/hourly"}'::jsonb,
    'FLZ041',
    'FLC127',
    null,
    true,
    'No lifeguards on duty - swim at your own risk. The water is a constant 72 F. Depths range from 18 inches to 30 ft at the spring boil, where a cave opens - free-diving into it is prohibited. Children and non-swimmers must be with an adult swimmer and stay inside the roped-off areas. Alligators live in Spring Garden Run, which is closed to swimming. The swim area closes when lightning is within 6 miles.',
    'https://www.floridastateparks.org/parks-and-trails/de-leon-springs-state-park',
    '/photos/de-leon-springs-state-park.jpg',
    '601 Ponce De Leon Blvd, De Leon Springs (386-985-4212), north of DeLand. No day-use reservations; first-come, first-served. Visitor reviews report the park at capacity on hot weekends (June 2026), but the park publishes no typical fill time, so none is listed. Pavilions cannot be reserved April 1 through Labor Day weekend. Expect a wait for the pancake house on weekends.',
    null,
    'A spring-fed swimming basin north of DeLand, walled like a pool and famous for the Old Spanish Sugar Mill pancake house beside the water. One of the easiest springs to get into, with stairs, handrails and a swimmer chair lift.'
)
