-- Weeki Wachee Springs State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'weeki-wachee-springs-state-park',
    'Weeki Wachee Springs State Park',
    'spring',
    'state',
    28.51694,
    -82.57343,
    'deep',
    true,
    'yes',
    '9 a.m. to 5:30 p.m. daily, year-round (concessionaire-run). Buccaneer Bay beach and swimming are open daily; water slides close 4:30 p.m. and swimming 5 p.m. Slides and lazy river run daily May 23-Aug 8, 2026, weekends only Mar 24-May 22 and Aug 9-Sep 30, 2026, and daily Mar 14-23 (spring break).',
    '$13 adults; $8 children 6-12; ages 5 and under free (covers the mermaid shows, river cruise and Buccaneer Bay). Lazy-river tube wristbands, beach chairs, cabanas and kayak rentals are extra.',
    false,
    null,
    '{"alcohol":"No glass or alcohol inside the park.","tubing":"Personal tubes and rafts are not permitted (child floats and pool noodles are fine). Tubes rented from the concessionaire are used on the lazy river - riders must be 42 in. or taller, one rider per tube.","pets":"Not permitted.","life_jackets":"Allowed in the swim area; not allowed on the water slides (nor masks, goggles or cameras).","other":["Coolers 45 quarts or smaller; no grilling, pop-up tents, tables of food, chafing dishes or personal speakers.","Slides: 48 in. minimum height for Cannonball, 42 in. for Pirate''s Revenge; no swimwear with buckles or rivets and no denim on slides.","No refunds or return tickets for weather closures; attractions can close for lightning.","Lil'' Mates kiddie pool is closed for renovations (2026)."]}'::jsonb,
    '02310500',
    '02310525',
    0.9,
    '{"gridId":"TBW","gridX":64,"gridY":122,"forecast":"https://api.weather.gov/gridpoints/TBW/64,122/forecast","forecastHourly":"https://api.weather.gov/gridpoints/TBW/64,122/forecast/hourly"}'::jsonb,
    'FLZ148',
    'FLC053',
    '11:00',
    true,
    'Certified lifeguards are on duty at Buccaneer Bay (concessionaire statement). The spring is about 72-74 F year-round. The spring vent is the deepest known freshwater cave system in the United States - no public diving or entering the cave. The swim area is a natural spring with a current toward the Weeki Wachee River; the beach and slides close for lightning and no refunds are issued.',
    'https://www.floridastateparks.org/WeekiWachee',
    '/photos/weeki-wachee-springs-state-park.jpg',
    '6131 Commercial Way (US 19 at SR 50), Weeki Wachee (352-610-5660). Run by concessionaire Guest Services; per-person admission at the gate, no reservation required. In summer the park often reaches capacity - once full, no more tickets are sold for the rest of the day and family members cannot join a party already inside. Third-party guides (2026) say it fills before noon on summer weekends and recommend arriving before the 9 a.m. opening; the 11 a.m. typical fill time is an estimate from those reports.',
    null,
    'The classic mermaid-show attraction on Florida''s Nature Coast, where Buccaneer Bay adds a white-sand beach, a lazy river and two water slides that drop into the first-magnitude spring. It is the only lifeguarded spring in this list, and it sells out on summer weekends.'
)
