-- Kelly Park / Rock Springs
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'kelly-park-rock-springs',
    'Kelly Park / Rock Springs',
    'spring',
    'county',
    28.75757,
    -81.49684,
    'deep',
    true,
    'yes',
    'Summer (March to early November) 8 a.m.-8 p.m.; winter (November to March) 8 a.m.-6 p.m. The waterfront and nature trails close one hour before park closing. Concession stand open daily spring break through early October.',
    '$5 per vehicle; $10 per bus (effective Aug 11, 2026). Cash, or Visa/MasterCard/Discover with photo ID. Tube rentals from vendors outside the park; camping extra.',
    false,
    null,
    '{"alcohol":"Not allowed anywhere on park property (Orange County ordinance).","tubing":"Float the 68-72 F Rock Springs Run (about 25 minutes), then a 10-minute walk back on a paved sidewalk - no shuttle. No rentals inside the park: rent from vendors outside or bring your own tube, noodle or float under 5 ft in length or width. No air pump on site.","pets":"No pets in the park or campground - ADA service animals only.","life_jackets":"Coast Guard-approved life jackets and puddle jumpers are allowed; water wings are not.","other":["Everyone must stay out of the cave at the spring head.","Pop-up canopies up to 10 x 10 ft in the picnic area only; no tents at the waterfront; grills only in picnic areas, never near the water.","The swim area closes when the lightning-prediction system triggers, or when lifeguards lose sight of the river bottom.","Get a re-entry stamp at the gatehouse before leaving to fetch tubes or food."]}'::jsonb,
    '02234610',
    '02235000',
    9.8,
    '{"gridId":"MLB","gridX":21,"gridY":77,"forecast":"https://api.weather.gov/gridpoints/MLB/21,77/forecast","forecastHourly":"https://api.weather.gov/gridpoints/MLB/21,77/forecast/hourly"}'::jsonb,
    'FLZ045',
    'FLC095',
    '09:00',
    true,
    'Lifeguards are on stand along the run during peak season only, not year-round - watch children closely. The water is 68-72 F year-round (colder than most springs) and the run is shallow and rocky. The cave at the spring head is off-limits. Alligators and snakes are occasionally seen in the water - tell staff. The swim area closes for lightning.',
    'https://www.ocfl.net/cultureparks/parks.aspx?d=22&m=dtlvw',
    '/photos/kelly-park-rock-springs.jpg',
    '400 E Kelly Park Rd, Apopka (407-254-1902; capacity info line 407-254-1906). Orange County park: 280 vehicles are admitted each morning; once full, the first 50 cars in line get passes for a 1 p.m. re-opening (one pass per car). Officially, on a typical summer day the park is full within an hour of opening, and visitors report lining up from 4:30 a.m. Family members cannot join a party already inside once the park is at capacity. The county web page and info line are updated when the park is full. Wekiwa Springs State Park (reservation-only) is the nearest backup.',
    null,
    'Orange County''s spring-fed tubing run north of Apopka, where a 68-degree spring feeds a shallow, rocky run through the woods to a sandy swim area and picnic lawns. It is the fastest-filling swimming hole in Central Florida, usually closing within an hour of opening on summer weekends.'
)
