-- ---------------------------------------------------------------- parks (extra tier)
-- Hart Springs Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'hart-springs-park',
    'Hart Springs Park',
    'spring',
    'county',
    29.67574,
    -82.95171,
    'deep',
    true,
    'no',
    'April 1 - September 30: 9 a.m. to 7:30 p.m. daily. October 1 - March 31: 9 a.m. to 5 p.m. daily.',
    'April - September: $5 per person Monday-Friday, $8 per person Saturday, Sunday and holidays. October - March: $3 per person. Children 5 and under and seniors 65 and over are free. Camping and the Hart Springs House are booked separately through ReserveAmerica.',
    false,
    'https://www.reserveamerica.com/',
    '{"alcohol":"No alcohol anywhere in the park, and intoxicated people are not admitted.","tubing":"Not a tubing run - the spring run is short and empties into the Suwannee River. No published tube rental or float trip.","pets":"No pets in the day-use springs area. Pets are allowed in the RV park and on the nature trails only, under the park''s pet policy.","life_jackets":"No published restriction on life jackets or personal flotation devices in the swimming area.","other":["No glass in common areas or in the springs.","No fishing in the swimming area.","Smoking and vaping are prohibited throughout the park, including the parking lots and the boardwalk.","Noise and music must stay in the vicinity of your shelter or picnic area.","No generators in the day-use area."]}'::jsonb,
    null,
    '02323500',
    9.7,
    null,
    null,
    null,
    null,
    false,
    'No lifeguards on duty - swim at your own risk. The spring stays about 72 F year round, cold enough to tire swimmers quickly. The spring run flows into the Suwannee River; when the river is high it backs into the spring pool and the water turns dark and loses visibility. Alligators and water snakes live in the river and can move into the run. The boardwalk and steps get slippery.',
    'https://hartsprings.com/',
    '/photos/extra/hart-springs-park.jpg',
    'Gilchrist County park at 4240 SW 86th Avenue, Bell. One gated day-use entrance with a staffed booth; the campground entrance is separate at 4183 SW 80th Ct. The park sets a daily capacity: once capacity is reached only people who already hold a wristband or have a shelter/pavilion reservation are let in, so a reserved shelter or Pavilion A or B guarantees your group entry on a busy day. Pay per person, not per car.',
    null,
    'A Gilchrist County park on the Suwannee River with one of the largest spring-fed swimming areas in Florida, plus a half-mile boardwalk along the spring run. It is a pay-per-person day-use park that stops admitting new visitors once it hits its daily capacity.'
)
