-- Lithia Springs Conservation Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'lithia-springs-conservation-park',
    'Lithia Springs Conservation Park',
    'spring',
    'county',
    27.86629,
    -82.23055,
    'deep',
    true,
    'unknown',
    '8 a.m. to 7 p.m. daily in spring and summer; 8 a.m. to 6 p.m. in fall and winter. The swimming area closes one hour before the park closes. Swimming runs in two four-hour slots: 9 a.m. to 1 p.m. and 2 p.m. to 6 p.m.',
    '$2 per vehicle to enter (up to 8 people per vehicle) plus $2 per person to swim. Camping is charged separately.',
    false,
    'https://flhillsboroughweb.myvscloud.com/webtrac/web/siterentals.html?location=LS&interfaceparameter=WebTracCELM',
    '{"alcohol":"Hillsborough County does not publish an alcohol rule for the Lithia Springs swim area; assume alcohol is not permitted in the spring and check at the gate.","tubing":"Not a tubing run. Round rings and inflatable toys are allowed in the shallow areas only.","pets":"Pets and service animals are not permitted inside the spring area. Elsewhere in the county park pets must be on a hand-held leash and picked up after.","life_jackets":"Arm floaties and life vests are allowed in all parts of the spring. No flotation devices in the deep end.","other":["Swim bands are sold at the gate only - they cannot be reserved ahead or bought over the phone, and there are no rain checks or refunds.","Each four-hour swim slot is capped at 200 swimmers.","No Bluetooth speakers in the swimming area.","No hammocks or anything attached to trees or the fence inside the swimming area.","No bounce houses in the park.","A responsible adult over 18 must supervise children under 12.","Swim bands are not sold in the hour before the swimming area closes.","Bands are sold only to people already at the park, and only for one of the two slots.","The swim area is sanitised between the two slots.","The swimming area closes for thunder, lightning and inclement weather.","Picnic shelters are not rented April-September; shelters, tables, grills and parking spaces are first come, first served."]}'::jsonb,
    null,
    '02301500',
    2,
    null,
    null,
    null,
    null,
    false,
    'Hillsborough County does not publish lifeguard coverage for the spring - plan on swimming at your own risk. The spring holds about 72 F year round and has a roped deep end where no flotation devices are allowed. The spring run empties into the Alafia River a short walk away; after heavy rain the river rises, the water turns murky and the county closes the spring for swimming. Alligators live in the Alafia River system.',
    'https://hcfl.gov/locations/lithia-springs-park',
    '/photos/extra/lithia-springs-conservation-park.jpg',
    'Hillsborough County park at 3932 Lithia Springs Rd., Lithia. One entrance station: you pay the $2 vehicle fee there and buy $2 swim bands for anyone going in the spring. Bands are sold in person only, for one of the two four-hour slots, and each slot is capped at 200 swimmers, so weekends and holidays sell out - arrive at the start of the slot. The park itself, the campground and the trails stay open even when the spring is closed.',
    null,
    'A Hillsborough County conservation park east of Tampa built around a clear, second-magnitude spring with a fenced swimming area and a campground. Swimming is sold in two capacity-limited four-hour sessions, so on hot weekends the bands run out well before the slot ends.'
)
