-- Hunter Springs Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'hunter-springs-park',
    'Hunter Springs Park',
    'spring',
    'county',
    28.89512,
    -82.59248,
    'basic',
    true,
    'no',
    '8 a.m. to 8 p.m. from April 1 (or the first day of daylight saving time, whichever comes first) through Labor Day; 8 a.m. to 7 p.m. from the day after Labor Day through October 31; 8 a.m. to 5:30 p.m. from November 1 (or the day after daylight saving ends, whichever is later) through March 31. Restrooms close 30 minutes before the park.',
    'Paid parking and a separate per-vessel paddle-craft launch fee, both collected at the pay station. Credit or debit card only - have your vehicle tag number ready. City of Crystal River resident annual parking passes are accepted in place of the parking fee; commercial and county launch passes are not valid here. The city does not publish the dollar amount online; third-party guides report about $5 to park and $5 per paddle-craft launch.',
    false,
    null,
    '{"alcohol":"No alcoholic beverages and no glass containers anywhere in the park.","tubing":"No tubing run. The swimming area is a roped-off freshwater beach on Kings Bay; the city rents no paddle-craft and commercial launching is not allowed.","pets":"No dogs or pets in the park. Service animals are permitted under Titles II and III of the ADA.","life_jackets":"No published restriction on life jackets in the roped swim area.","other":["No jumping, diving or climbing from or on the boardwalk.","No fishing anywhere in the park or from the shoreline.","No tents, canopies or umbrellas over 4 feet across.","No loud sound-making devices; no smoking except in designated areas.","No oversized vehicle or trailer parking, and no overnight parking - cars left at closing may be towed.","Children 12 and under may not be left unattended.","Do not feed or disturb the manatees and other wildlife."]}'::jsonb,
    null,
    '02310742',
    1.3,
    null,
    null,
    null,
    null,
    false,
    'No lifeguards - swim at your own risk. The spring vent sits about 100 feet offshore and keeps the water near 72 F year round. This is open water on Kings Bay: boat traffic runs just outside the swim buoys, manatees are present (especially November to March) and must not be touched or chased, and alligators occasionally enter the bay. The bottom drops off and visibility falls after wind or heavy rain.',
    'https://www.crystalriverfl.org/comserv/page/hunter-springs-park',
    '/photos/extra/hunter-springs-park.jpg',
    'City of Crystal River park at 104 NE 1st Ave, a residential street corner with a small paid lot - no oversized vehicles or trailers. Pay at the station by card with your tag number before you walk in. The lot is the limiting factor on manatee-season weekends; overflow parking in the neighbourhood is restricted and cars left at closing are towed.',
    null,
    'A small city park on Kings Bay in Crystal River with a sandy freshwater beach, a roped swim area fed by an offshore spring vent, a kayak launch and a manatee-viewing boardwalk. The water stays about 72 F all year, which is why manatees crowd in during cold months.'
)
