-- Little River Springs Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'little-river-springs-park',
    'Little River Springs Park',
    'spring',
    'county',
    29.99685,
    -82.96636,
    'basic',
    true,
    'unknown',
    'April - October: 9 a.m. to 7 p.m. November - March: 9 a.m. to 5 p.m. Open year round.',
    '$5 per vehicle entrance fee.',
    false,
    null,
    '{"alcohol":"No alcohol allowed.","tubing":"No tubing run. The spring run is only about 150 feet long before it reaches the Suwannee River.","pets":"No pets allowed.","life_jackets":"No published restriction on life jackets in the spring.","other":["Open water swimming and snorkelling in the spring pool and run; picnic pavilions and portable restrooms on site.","The underwater cave is for cave-certified divers only - open-water divers and snorkellers must stay out of the cave."]}'::jsonb,
    null,
    '02320500',
    5.9,
    null,
    null,
    null,
    null,
    true,
    'No published lifeguard coverage - swim at your own risk. The water is about 72 F year round and the spring pool drops off steeply to the cave entrance. More than 1,200 feet of underwater cave runs back from the vent and it is a well-known cave-diving site: entering it without cave certification, lights and a guideline is how divers die here. The run empties into the Suwannee River, so when the river is high it pushes tannic water back into the pool and visibility disappears. Alligators use the river.',
    'https://suwanneeparks.com/little-river-springs/',
    '/photos/extra/little-river-springs-park.jpg',
    'Suwannee County park at 24891 105th Ln., O''Brien, about 3 miles north of Branford. One gated entrance with a $5 per-vehicle honour/attendant fee - this fee only started recently, so older guides that call it free are out of date. Paved parking, paved walkways and three accessible pavilions; restrooms are portable units. Divers and swimmers share the same small pool.',
    null,
    'A 125-acre Suwannee County park on the Suwannee River, built around a clear spring pool that stays near 72 F all year. It is popular with swimmers and snorkellers and is also the entrance to a long underwater cave system that draws cave divers from around the world.'
)
