-- Royal Springs Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'royal-springs-park',
    'Royal Springs Park',
    'spring',
    'county',
    30.08375,
    -83.07483,
    'basic',
    true,
    'unknown',
    'April - October: 9 a.m. to 7 p.m. November - March: 9 a.m. to 5 p.m. Open year round.',
    '$5 per vehicle entrance fee.',
    false,
    null,
    '{"alcohol":"No alcohol allowed.","tubing":"No tubing run. The spring boil sits beside the Suwannee River with a short run.","pets":"No pets allowed.","life_jackets":"No published restriction on life jackets in the spring.","other":["Two sets of stairs lead into the water and there is a jumping/diving platform over the boil.","A one-lane concrete boat ramp gives access to the Suwannee River - keep clear of the ramp when swimming.","Restrooms on site are portable units."]}'::jsonb,
    null,
    '02320000',
    9.5,
    null,
    null,
    null,
    null,
    false,
    'No published lifeguard coverage - swim at your own risk. The spring stays about 72 F year round, cold enough to tire swimmers quickly, and the boil is deep right under the jumping platform - check the depth and clear the water below before anyone jumps. The stairs and platform get slippery. The spring sits next to the Suwannee River and a boat ramp; when the river runs high it floods the boil with dark water and swimming is not worth it. Alligators use the river.',
    'https://suwanneeparks.com/royal-springs/',
    '/photos/extra/royal-springs-park.jpg',
    'Suwannee County park at 20091 157th Ln., O''Brien, in a rural stretch south of Live Oak. One entrance with a $5 per-vehicle fee. The lot also serves the boat ramp, so it fills with trailers on good river days. Facilities are basic: one picnic pavilion, tables and grills, and portable toilets.',
    null,
    'A small Suwannee County park on the Suwannee River whose large spring boil is popular with swimmers, snorkellers and jumpers from the platform above it. Stairs lead into the water and a one-lane ramp next door launches boats onto the river.'
)
