-- Suwannee Springs
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'suwannee-springs-park',
    'Suwannee Springs',
    'spring',
    'county',
    30.39448,
    -82.93454,
    'basic',
    true,
    'no',
    'Daylight hours only: 1.5 hours before sunrise to 1.5 hours after sunset, unless otherwise posted. No overnight parking.',
    'Free - no entrance or parking fee on Suwannee River Water Management District lands.',
    false,
    null,
    '{"alcohol":"Alcoholic beverages, intoxicants and illegal drugs are prohibited on District lands.","tubing":"No organised tubing run. People float and swim in the river and off the white sand bars beside the spring house.","pets":"Dogs are allowed but must be on a leash.","life_jackets":"No published restriction on life jackets; the Suwannee River here has current, so wear one if you are not a strong swimmer.","other":["Scuba diving is prohibited on District lands.","No fires of any kind.","Camping only by special use authorisation - this is a day-use site.","Do not remove plants, animals or anything from the historic 1800s spring house."]}'::jsonb,
    null,
    '02315550',
    0.2,
    null,
    null,
    null,
    null,
    false,
    'No lifeguards and no staff on site - the District states plainly that it gives no assurance the area is safe. This is a sulphur spring inside a roofless 1800s limestone spring house right on the bank of the Suwannee River: the water smells of sulphur, is about 72 F, and the walls are old, uneven and slick. The river itself has current and dark tannic water, and when it rises it floods the spring house completely and the swimming is gone until it drops. Alligators and water snakes use the river.',
    'https://map.mysuwanneeriver.com/tracts/suwannee-springs-212/',
    '/photos/extra/suwannee-springs-park.jpg',
    'A 115-acre Suwannee River Water Management District tract (the District is a regional public agency, not a county - LakeLens files public non-state sites like this under ''county''). From US 129 north of Live Oak turn onto 93rd Drive (Old US 129), go north to 32nd Street and turn right to the parking lot. Unstaffed and free; facilities are a picnic area, restrooms and a canoe launch. Check the Suwannee River gauge at Suwannee Springs (USGS 02315550, essentially on site) before you drive out - a high river means the spring house is under water.',
    null,
    'A free, unstaffed water-management-district tract on the Suwannee River where a sulphur spring bubbles up inside the stone walls of an 1800s spring house. People swim in the spring house and off the white sand bars along the river beside it.'
)
