-- Otter Springs Park & Campground
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'otter-springs-park',
    'Otter Springs Park & Campground',
    'spring',
    'county',
    29.64457,
    -82.94315,
    'basic',
    true,
    'unknown',
    'Gilchrist County does not publish day-use hours online. Call the park at (352) 463-0800 before you go.',
    'Gilchrist County does not publish a day-use fee online; an entry fee is charged. Campsites and cabins are booked through ReserveAmerica. Call (352) 463-0800 to confirm.',
    false,
    'https://www.reserveamerica.com/',
    '{"alcohol":"No alcohol rule is published for the day-use area; Gilchrist County''s other spring park (Hart Springs) bans alcohol outright, so expect the same and confirm at the gate.","tubing":"No tubing run. Swimming is in the spring in the picnic area or in the swimming pool, which is heated in winter.","pets":"No pet policy is published for the day-use area; confirm with the park.","life_jackets":"No published restriction on life jackets.","other":["Two separate places to swim: the second-magnitude spring in the picnic area and a heated swimming pool.","Hiking trails run from the park down to the Suwannee River.","Basketball court and volleyball net on site."]}'::jsonb,
    null,
    '02323500',
    6.1,
    null,
    null,
    null,
    null,
    false,
    'No published lifeguard coverage for the spring - swim at your own risk. The spring holds about 72 F year round. The spring run drains to the Suwannee River a short walk away, so a high river backs tannic water up into the spring and kills the clarity; the pool is the fallback on those days. Alligators use the river and the lower run.',
    'https://visitgilchristcounty.com/otter-springs/',
    '/photos/extra/otter-springs-park.jpg',
    'Gilchrist County park at 6470 SW 80th Avenue, Trenton, just east of Fanning Springs. The county took management of the park back in-house on 16 February 2026 after it had been run under contract, and the park reopened on 1 May 2026, so hours, fees and rules published before 2026 are unreliable - phone (352) 463-0800 or the county at (352) 463-3444 to confirm before driving out.',
    null,
    'A 500-acre Gilchrist County park and campground near Fanning Springs with a second-magnitude spring in the picnic area and a separate heated swimming pool. Trails run from the campground down to the Suwannee River.'
)
