-- Morrison Springs County Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'morrison-springs-park',
    'Morrison Springs County Park',
    'spring',
    'county',
    30.65788,
    -85.90394,
    'basic',
    true,
    'no',
    'Open daily, sunrise to sunset. The park closes at dusk - there is no night diving, by Walton County ordinance 2007-09.',
    '$4 per vehicle at the gate. Credit or debit card only - no cash is accepted. The fee started on 1 March 2026; guides written before then that call the park free are out of date.',
    false,
    null,
    '{"alcohol":"Walton County does not publish an alcohol rule on the park page; third-party guides report alcohol and loud music are not allowed. Confirm at the entrance building.","tubing":"No tubing run. The spring pool drains through a short run to the Choctawhatchee River.","pets":"No pet policy is published on the county park page - confirm at the gate.","life_jackets":"No published restriction on life jackets in the spring pool.","other":["No night diving (county ordinance 2007-09); the park closes at dusk.","No motorized boats upstream of the boat ramp toward the spring - kayaks and row boats only.","The boat ramp is more than 100 yards from the diving area, so boat traffic and divers stay separated.","Outdoor shower heads at the restrooms for swimmers and divers."]}'::jsonb,
    null,
    '02365500',
    15,
    null,
    null,
    null,
    null,
    true,
    'No lifeguards - swim at your own risk. The spring pool is about 250 feet across and holds roughly 72 F water year round. Three cavern openings lead down from the pool and the deepest cavity reaches about 300 feet: the shallow openings are cavern dives, and the deep system is for cave-certified divers with proper gear only. Divers and swimmers share the same pool, so watch for bubbles and dive flags. When the Choctawhatchee River floods it backs tannic water into the spring and clarity disappears - Walton County publishes a 1-5 water clarity rating on the park page.',
    'https://www.mywaltonfl.gov/523/Morrison-Springs',
    '/photos/extra/morrison-springs-park.jpg',
    'Walton County park at 874 Morrison Springs Road, Ponce de Leon - a 161-acre site off SR 81. Since March 2026 there is an entrance building with a card-only $4 per-vehicle gate; bring a card, not cash. Wheelchair-accessible boardwalks run to the diver''s dock and to the beach area, with accessible parking near the pavilions. The boat ramp has its own separate parking lot.',
    null,
    'A Walton County park in the Florida Panhandle built around a wide, clear spring pool that pushes out roughly 48 million gallons a day. It is one of northwest Florida''s best-known dive sites and also a straightforward place to swim from the beach and boardwalks.'
)
