-- Vortex Spring Adventures
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'vortex-spring',
    'Vortex Spring Adventures',
    'spring',
    'private',
    30.77067,
    -85.94838,
    'basic',
    true,
    'no',
    'Monday to Thursday 10 a.m. to 5 p.m.; Friday to Sunday 8 a.m. to 5 p.m. (Central time). Open year round except Thanksgiving and Christmas. Quiet hours midnight to 8 a.m. in the campground.',
    'Day use $15 for ages 13 and up, $10 for ages 12 and under, free under 4 (plus tax). Snorkel gear add-on $6. Daily diving pass $25. Camping, cabins and golf-cart rental are extra.',
    false,
    'https://vortexspring.com/',
    '{"alcohol":"Personal alcohol is allowed for guests of legal age, but you may not sell or serve alcohol to other guests. Divers must never dive under the influence of alcohol or drugs.","tubing":"No tubing run. Swimming, snorkelling and diving are all in the spring basin and its short run.","pets":"Pets are allowed in designated campground areas only, on a leash no longer than 6 feet and cleaned up after. They are not allowed near the spring, swim areas, decks, docks, slides or platforms, or in lodging, retail or the restaurant. Service animals are allowed anywhere guests may go.","life_jackets":"No published restriction on life jackets. Everyone must sign a waiver before swimming - adults sign their own, a parent or guardian signs for minors.","other":["Glass is prohibited everywhere in the spring and pool areas - drinks must be in cans or sealed plastic.","Divers must show certification; minimum diving age is 10 and minors must dive with a certified adult.","No cavern or cave entry without the matching certification.","Golf carts and ATVs need proof of liability insurance and a signed waiver.","Admission can be revoked without refund for breaking park rules."]}'::jsonb,
    null,
    null,
    null,
    null,
    null,
    null,
    null,
    true,
    'Privately run, with waivers instead of lifeguards - swim at your own risk. The basin holds about 68 F water year round, colder than most Florida springs, and it is deep. This is a cave system with a history: after a run of fatalities the operators installed a locked steel gate roughly 300 feet into the cave at about 110 feet deep, and only cave-certified divers get it opened, usually with a staff member. Open-water divers and snorkellers must stay out of the cave. Bubbles and dive flags are everywhere - swimmers should keep clear of the dive platforms.',
    'https://vortexspring.com/',
    '/photos/extra/vortex-spring.jpg',
    'Privately owned resort at 1517 Vortex Springs Lane, Ponce de Leon (Holmes County) - not a public park, so county and state park passes do not apply and admission is charged per person at the gate. Everyone signs a waiver before getting in the water. The dive shop handles diving check-in and rentals; call (850) 836-4979 to confirm trail and facility availability, which changes with weather and events.',
    null,
    'A privately run spring resort in the Panhandle with a walled swimming basin, dive platforms, a dive shop, campground and cabins. It is best known as a training site for divers, with a gated cave system that only cave-certified divers may enter.'
)
