-- Williford Spring Recreation Area
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'williford-spring',
    'Williford Spring Recreation Area',
    'spring',
    'county',
    30.439702,
    -85.547447,
    'basic',
    true,
    'no',
    '8 a.m. until sunset, seven days a week. Day use only.',
    'Free - no entrance or parking fee.',
    false,
    null,
    '{"alcohol":"Alcoholic beverages are prohibited throughout the Econfina Creek Water Management Area.","tubing":"Tubing on Econfina Creek runs from the Pitt and Sylvan Springs site downstream; Williford has a canoe/kayak launch at the end of the boardwalk, but no vessels are allowed in the spring itself.","pets":"No pet rule is published for this site; dogs are generally allowed on District lands under control.","life_jackets":"No published restriction on life jackets.","other":["No vessels - canoes, kayaks, paddleboards - inside the spring area.","No ATVs anywhere in the water management area; motorized vehicles on designated roads only.","Three first-come picnic pavilions and two composting toilets; no drinking water.","A mile-long nature trail connects to Pitt and Sylvan Springs."]}'::jsonb,
    null,
    '02359500',
    6.2,
    null,
    null,
    null,
    null,
    false,
    'No lifeguards and no staff on site - swim at your own risk. The spring runs about 72 F year round. Entry is by steps with handrails into a boil that is deeper than it looks; the boardwalk and steps are slick. The spring run joins Econfina Creek within a few hundred feet, and the creek has real current plus snags - after heavy rain it rises fast and turns dark. Alligators and water snakes use the creek. Only composting toilets and no drinking water, so bring your own.',
    'https://nwfwater.com/Lands/Recreation/Area/Econfina-Creek/Williford-Spring/',
    '/photos/extra/williford-spring.jpg',
    'A Northwest Florida Water Management District recreation site at 5647 Porter Pond Road, Youngstown, in Washington County (the District is a regional public land-management agency, not a county - LakeLens files public non-state sites like this under ''county''). From US 231 go about 7 miles west and turn north onto Porter Pond Road, roughly 1.5 miles north of SR 20. Free and unstaffed, with a boardwalk system around the spring, mobility access and steps with handrails into the water. The small gravel lot is the limit on summer weekends.',
    null,
    'A free water-management-district site on Econfina Creek in the Panhandle, with a boardwalk ringing a clear spring and handrailed steps down into the boil. A nature trail links it to the Pitt and Sylvan Springs site about a mile away.'
)
