-- Pitt and Sylvan Springs Recreation Area
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'pitt-spring-recreation-area',
    'Pitt and Sylvan Springs Recreation Area',
    'spring',
    'county',
    30.432718,
    -85.546503,
    'basic',
    true,
    'no',
    '8 a.m. until sunset, seven days a week. Day use only.',
    'Free - no entrance or parking fee. Tube and shuttle rentals from private outfitters on SR 20 are separate.',
    false,
    null,
    '{"alcohol":"Alcoholic beverages are prohibited throughout the Econfina Creek Water Management Area.","tubing":"Yes - this is the Econfina Creek tubing site. There is a tube put-in dock at the Sylvan Spring end and a take-out dock where the Pitt Spring run meets Econfina Creek.","pets":"No pet rule is published for this site; dogs are generally allowed on District lands under control.","life_jackets":"No published restriction on life jackets; Econfina Creek has current, so wear one if you are not a strong swimmer.","other":["Day use only - no camping.","Swimming area has safety railings.","Canoe/kayak launch with a tie-up area for a quick stop.","Composting restrooms and first-come picnic pavilions; overflow parking is reached from Porter Pond Road.","No ATVs; motorized vehicles on designated roads only."]}'::jsonb,
    null,
    '02359500',
    5.4,
    null,
    null,
    null,
    null,
    false,
    'No lifeguards and no staff on site - swim at your own risk. The springs run about 72 F. This is the busiest tubing put-in on Econfina Creek, so expect tube traffic in the run on summer weekends. The creek is not a lazy river: it has current, undercut banks, submerged logs and a few pinch points, and after heavy rain it rises fast and turns dark - check the Econfina Creek gauge near Bennett before floating. Alligators and water snakes use the creek. Composting toilets only and no drinking water.',
    'https://nwfwater.com/Lands/Recreation/Area/Econfina-Creek/Pitt-and-Sylvan-Springs/',
    '/photos/extra/pitt-spring-recreation-area.jpg',
    'A 10-acre Northwest Florida Water Management District site at 6315 E. Highway 20, Youngstown, in Bay County (the District is a regional public land-management agency, not a county - LakeLens files public non-state sites like this under ''county''). Free and unstaffed, right on SR 20. The main lot fills on summer weekends; overflow parking is off Porter Pond Road. A mile-long connector trail runs to Williford Spring.',
    null,
    'A free water-management-district site on Econfina Creek where Pitt and Sylvan springs feed a short clear run into the creek. It has railed swimming areas, boardwalks, and the put-in and take-out docks for the Econfina Creek tube float.'
)
