-- Cypress Spring
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'cypress-spring',
    'Cypress Spring',
    'spring',
    'county',
    30.65875,
    -85.68437,
    'basic',
    true,
    'no',
    'Daylight hours. There is no gate and no staff - it is reached from the water on Holmes Creek.',
    'Free to reach by your own boat. Private outfitters on Cypress Springs Road and at Holmes Creek landings charge for kayak, canoe and paddleboard rental and shuttles.',
    false,
    null,
    '{"alcohol":"Alcoholic beverages are prohibited on Holmes Creek (Northwest Florida Water Management District rule).","tubing":"People float and paddle the Holmes Creek run past the spring; there is no formal tube launch at the spring itself.","pets":"No pet rule is published for this site; dogs are generally allowed on District lands under control.","life_jackets":"No published restriction, but this is a creek paddle - Florida law requires a wearable life jacket aboard for every person and children under 6 must wear one on a vessel under 26 feet.","other":["No ATVs; motorized vehicles on designated roads only.","No facilities at the spring - no restrooms, no drinking water, no trash service. Pack it out.","Watch for the federally protected Gulf sturgeon, which congregate in the lower Choctawhatchee near the Holmes Creek confluence."]}'::jsonb,
    null,
    '02366000',
    4.4,
    null,
    null,
    null,
    null,
    true,
    'No lifeguards, no staff and no phone signal to speak of - this is a remote, water-access spring. The boil is about 72 F and deep, with a cavern vent that divers enter; snorkellers and untrained divers must stay out of it. Holmes Creek has current and boat traffic, and when the Choctawhatchee system rises the creek floods the spring with dark water and the swimming is over until it drops - check the Holmes Creek gauge at Vernon first. Alligators and water snakes use the creek.',
    'https://nwfwater.com/lands/recreation/area/choctawhatchee-river-holmes-creek/',
    '/photos/extra/cypress-spring.jpg',
    'A first-magnitude spring on Holmes Creek in Washington County, protected by the Northwest Florida Water Management District with Washington County (the District is a regional public land-management agency, not a county - LakeLens files public non-state sites like this under ''county''). Note the spring is on Holmes Creek, not Econfina Creek. There is no road-side public park: the usual approach is a paddle from Cypress Springs Road or a Holmes Creek landing such as Cotton Landing. The District began a shoreline restoration project here on 8 January 2026 - shoreline access may still be restricted, but the spring stays reachable by watercraft.',
    null,
    'A big, clear first-magnitude spring on Holmes Creek in the Panhandle, reached by paddling rather than by driving to a car park. Swimmers and snorkellers float in the boil while the creek carries on past it.'
)
