-- ---------------------------------------------------------------- parks (basic tier)
-- Alfred B. Maclay Gardens State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'alfred-b-maclay-gardens-state-park',
    'Alfred B. Maclay Gardens State Park',
    'lake',
    'state',
    30.52859,
    -84.26017,
    'basic',
    true,
    'unknown',
    'Park and historic gardens open 8 a.m. to sunset daily, 365 days a year. Maclay House museum 9 a.m. to 5 p.m. daily, January through April.',
    '$6 per vehicle (up to 8 people); $4 single-occupant vehicle; $2 pedestrians, bicyclists and extra passengers. Garden entry is extra January through April: $6 adults, $3 ages 2-12.',
    false,
    null,
    '{"alcohol":"Prohibited. Alcoholic beverages are not allowed in Florida state parks (F.A.C. 62D-2.014).","pets":"Pets are welcome on a 6-foot leash in most of the park but not inside the formal gardens or the swimming area.","other":["Only boats without gas-powered motors are allowed on Lake Hall."]}'::jsonb,
    null,
    '02329000',
    12.2,
    '{"gridId":"TAE","gridX":85,"gridY":90,"forecast":"https://api.weather.gov/gridpoints/TAE/85,90/forecast","forecastHourly":"https://api.weather.gov/gridpoints/TAE/85,90/forecast/hourly"}'::jsonb,
    'FLZ017',
    'FLC073',
    null,
    false,
    'Swimming is in Lake Hall, a natural lake, so expect limited visibility and a natural bottom. Boats with gas motors are not allowed on the lake, but paddlers share the water with swimmers.',
    'https://www.floridastateparks.org/MaclayGardens',
    '/photos/basic/alfred-b-maclay-gardens-state-park.jpg',
    '3540 Thomasville Road, Tallahassee FL 32309 (850-487-4556), on US 319 north of I-10. No day-use reservations. Pets, food and drink are not permitted inside the formal gardens. Coordinates are the park centroid, not the swim area.',
    null,
    'Best known for its historic ornamental gardens, this Tallahassee park also has Lake Hall, where you can swim, fish and paddle from a lakeshore picnic area with pavilions and grills. Two short nature trails overlook the lake.'
)
