-- Blackwater River State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'blackwater-river-state-park',
    'Blackwater River State Park',
    'river',
    'state',
    30.70738,
    -86.87561,
    'basic',
    true,
    'no',
    '8 a.m. to sundown, 365 days a year (Central time). Ranger station staffed 3 to 5 p.m.',
    '$4 per vehicle (up to 8 people), paid at the honor box - correct change required; $2 pedestrians, bicyclists and extra passengers; $2 for Florida National Guard members and Florida EBT card holders.',
    false,
    null,
    '{"alcohol":"Prohibited. Alcoholic beverages are not allowed in Florida state parks (F.A.C. 62D-2.014).","tubing":"Allowed; bring your own tube (rentals from Blackwater Canoe Rental, 850-623-0235). All floats end at Deaton Bridge - no river access beyond it.","pets":"Pets are welcome on a 6-foot handheld leash but are not permitted on the beaches or in the water.","life_jackets":"Recommended by the park for anyone who is not a strong swimmer (USCG-approved).","other":[]}'::jsonb,
    null,
    '02370500',
    9.2,
    '{"gridId":"MOB","gridX":96,"gridY":70,"forecast":"https://api.weather.gov/gridpoints/MOB/96,70/forecast","forecastHourly":"https://api.weather.gov/gridpoints/MOB/96,70/forecast/hourly"}'::jsonb,
    'FLZ203',
    'FLC113',
    null,
    false,
    'Lifeguards are not on duty; the park recommends that anyone who is not a strong swimmer wear a U.S. Coast Guard-approved life jacket. The river is tannin-tinted but clear over white sandbars, with current and shifting sand; water levels change - call 850-983-5363 for current levels. There is no river access below Deaton Bridge and a major blockage downstream.',
    'https://www.floridastateparks.org/parks-and-trails/blackwater-river-state-park',
    '/photos/basic/blackwater-river-state-park.jpg',
    '7720 Deaton Bridge Road, Milton FL 32564 (850-983-5363); GPS routing is unreliable - double-check directions. No reservations; pay at the honor box. Three paved river-access lots plus a dirt canoe-trail lot: the Deaton Bridge lots are small and fill early on summer weekends and holidays, so use the pavilion parking area half a mile north of the bridge, which has plenty of space and a boardwalk to the main swim area. Coordinates are the park centroid, not the swim area.',
    null,
    'Two miles of the golden-brown, sand-bottomed Blackwater River run through this Panhandle park near Milton, with white sandbar beaches, a boardwalk to the main swimming area, two large pavilions and an outdoor shower. Tubing and paddling end at Deaton Bridge inside the park.'
)
