-- Edward Ball Wakulla Springs State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'edward-ball-wakulla-springs-state-park',
    'Edward Ball Wakulla Springs State Park',
    'spring',
    'state',
    30.24193,
    -84.30282,
    'basic',
    true,
    'unknown',
    '8 a.m. to sundown, 365 days a year. The swimming area opens by 8:30 a.m.; its closing time is posted daily and depends on daylight. It closes when thunderstorms threaten and reopens once they pass.',
    '$6 per vehicle (2-8 people); $4 single-occupant vehicle; $2 per extra occupant; $2 pedestrian or bicyclist. River boat tours $8 (13+), $5 (ages 3-12), free under 3.',
    false,
    null,
    '{"alcohol":"Prohibited. Alcoholic beverages are not allowed in Florida state parks (F.A.C. 62D-2.014).","pets":"Pets are welcome in the park on a 6-foot leash but are not allowed in the swimming area (statewide rule).","other":["Swim and snorkel only inside the designated swimming area near the spring.","Recreational scuba diving is not allowed in Wakulla Spring or the swimming area; open-water diving is at Cherokee Sink with check-in at the entrance station."]}'::jsonb,
    '02327000',
    '02327022',
    5,
    '{"gridId":"TAE","gridX":84,"gridY":78,"forecast":"https://api.weather.gov/gridpoints/TAE/84,78/forecast","forecastHourly":"https://api.weather.gov/gridpoints/TAE/84,78/forecast/hourly"}'::jsonb,
    'FLZ027',
    'FLC129',
    null,
    true,
    'The spring water is about 69-70 F year-round. Alligators and manatees live in the spring and river, so swim only inside the designated swimming area near the spring head. A 22-foot dive/observation tower stands over deep water. The swim area closes when thunderstorms threaten. Recreational scuba is not allowed in the spring or swim area; the vent is a cave system and cave diving is only for certified cave divers at Emerald Sink (Clear Cut Sink closed for research from June 14, 2026).',
    'https://www.floridastateparks.org/WakullaSprings',
    '/photos/basic/edward-ball-wakulla-springs-state-park.jpg',
    '465 Wakulla Park Drive, Wakulla Springs FL 32327 (850-561-7276), off SR 61 south of Tallahassee. No day-use reservations. Coordinates are the park centroid, not the swim area.',
    null,
    'One of the world''s largest and deepest freshwater springs, with 70 F water, a 22-foot dive and observation tower and a grassy beach along the Wakulla River, all beside a 1930s lodge and guided riverboat tours. Swimming is allowed only in the designated area near the spring head.'
)
