-- Falling Waters State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'falling-waters-state-park',
    'Falling Waters State Park',
    'lake',
    'state',
    30.72843,
    -85.52954,
    'basic',
    true,
    'unknown',
    '8 a.m. to sundown, 365 days a year.',
    '$5 per vehicle (2-8 people); $4 single-occupant vehicle; $2 pedestrians, bicyclists and extra passengers. Pavilions $30-$50 per day plus tax.',
    false,
    null,
    '{"alcohol":"Prohibited. Alcoholic beverages are not allowed in Florida state parks (F.A.C. 62D-2.014).","pets":"Pets are welcome on a 6-foot leash and must be well behaved; pick up after them. Pets are not allowed in the swimming area (statewide rule).","other":["A Florida freshwater fishing licence is required for anglers over 16."]}'::jsonb,
    null,
    null,
    null,
    '{"gridId":"TAE","gridX":36,"gridY":96,"forecast":"https://api.weather.gov/gridpoints/TAE/36,96/forecast","forecastHourly":"https://api.weather.gov/gridpoints/TAE/36,96/forecast/hourly"}'::jsonb,
    'FLZ010',
    'FLC133',
    null,
    false,
    'The swimming lake is a small (two-acre) freshwater lake with a white sand beach; no lifeguard is stated on the official page, so treat it as unguarded. The waterfall and sinkholes are on a separate boardwalk trail - the sinkholes are up to 100 feet deep, so stay on the boardwalk. Waterfall flow depends on recent rain.',
    'https://www.floridastateparks.org/parks-and-trails/falling-waters-state-park',
    '/photos/basic/falling-waters-state-park.jpg',
    '1130 State Park Road, Chipley FL 32428 (850-638-6130), about 3 miles south of I-10 exit 120. No day-use reservations. Picnic pavilions are first-come unless reserved. Coordinates are the park centroid, not the swim area.',
    null,
    'Home to Florida''s highest waterfall, which drops 73 feet into a sinkhole, plus a two-acre lake with a white sand beach, rinse shower, restrooms and changing space for swimmers. The hilly park sits a few miles south of I-10 near Chipley.'
)
