-- Florida Caverns State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'florida-caverns-state-park',
    'Florida Caverns State Park',
    'spring',
    'state',
    30.81286,
    -85.23396,
    'basic',
    true,
    'no',
    'Day-use area open 8 a.m. to sunset CST, 365 days a year. Cave tours 9 a.m. to 4 p.m. CST daily (closed on scheduled maintenance dates).',
    '$5 per vehicle (2-8 people); $4 single-occupant vehicle; $2 pedestrians, bicyclists and extra passengers. Cave tours extra: $16 ages 13+, $9 ages 3-12, free 2 and under.',
    false,
    null,
    '{"alcohol":"Prohibited. Alcoholic beverages are not allowed in Florida state parks (F.A.C. 62D-2.014).","pets":"Pets are permitted under the Florida State Parks pet policy (6-foot leash) but not in the swimming area (statewide rule).","other":["The park closes at sunset and visitors must be out by then.","Only small boats are recommended at the ramp; do not travel south under the bridge."]}'::jsonb,
    null,
    '02358789',
    4.7,
    '{"gridId":"TAE","gridX":47,"gridY":100,"forecast":"https://api.weather.gov/gridpoints/TAE/47,100/forecast","forecastHourly":"https://api.weather.gov/gridpoints/TAE/47,100/forecast/hourly"}'::jsonb,
    'FLZ011',
    'FLC063',
    null,
    true,
    'No lifeguards on duty - swim at your own risk. The Blue Hole swimming area is about 35 feet deep. Because it sits next to the Chipola River it sometimes has dark water and may close when the river floods. The park is a cave system: guided cave tours are on land, and moving water in the park is dangerous.',
    'https://www.floridastateparks.org/parks-and-trails/florida-caverns-state-park',
    '/photos/basic/florida-caverns-state-park.jpg',
    '3345 Caverns Road, Marianna FL 32446 (850-482-1228), in the Central time zone. No day-use reservations; cave tour tickets are first-come at the gift shop from 9 a.m. CST and often sell out on weekends. Park at the Blue Hole day-use area for swimming. Coordinates are the park centroid, not the swim area.',
    null,
    'Florida''s only state park with guided tours through a large limestone cave, plus the Blue Hole, a deep spring-fed swimming area beside the Chipola River. The swim area can turn dark or close when the river is high.'
)
