-- Lake Louisa State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'lake-louisa-state-park',
    'Lake Louisa State Park',
    'lake',
    'state',
    28.44704,
    -81.74114,
    'basic',
    true,
    'no',
    '8 a.m. to sundown, 365 days a year. All boats must be off the water an hour before sunset.',
    '$5 per vehicle (2-8 people); $4 single-occupant vehicle; $2 pedestrians, bicyclists and extra passengers.',
    false,
    null,
    '{"alcohol":"Prohibited. Alcoholic beverages are not allowed in Florida state parks (F.A.C. 62D-2.014).","pets":"Pets are allowed on a 6-foot handheld leash in day-use areas and trails but not at the playground, swimming area, cabins or park buildings.","other":["Swim only in the designated Lake Louisa swimming area; no swimming in the other lakes.","Boats must be hand-carried to the water; electric trolling motors only, no gas motors."]}'::jsonb,
    null,
    '02236500',
    0.1,
    '{"gridId":"MLB","gridX":13,"gridY":63,"forecast":"https://api.weather.gov/gridpoints/MLB/13,63/forecast","forecastHourly":"https://api.weather.gov/gridpoints/MLB/13,63/forecast/hourly"}'::jsonb,
    'FLZ144',
    'FLC069',
    null,
    false,
    'No lifeguards on duty - swim at your own risk, and only in the designated swimming area on Lake Louisa; swimming is not permitted in the park''s other lakes. The water is tea-coloured from natural tannins, so you may not be able to see the bottom even in shallow water. The beach bathhouse has cold, non-potable water only.',
    'https://www.floridastateparks.org/parks-and-trails/lake-louisa-state-park',
    '/photos/basic/lake-louisa-state-park.jpg',
    '7305 US Highway 27, Clermont FL 34714 (352-394-3969). No day-use reservations. The Lake Louisa day-use area (swimming, picnic tables and grills) is first-come, first-served - arrive soon after opening on busy days to get a table. Coordinates are the park centroid, not the swim area.',
    null,
    'A large park 30 minutes from Orlando with rolling hills, 20 miles of trails and several lakes; swimming is allowed in a designated area on tannin-stained Lake Louisa, next to a shaded picnic area, bathhouse and fully accessible playground. Dixie Lake has boat rentals and cabins.'
)
