-- Lake Manatee State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'lake-manatee-state-park',
    'Lake Manatee State Park',
    'lake',
    'state',
    27.47846,
    -82.33725,
    'basic',
    true,
    'no',
    '8 a.m. to sundown, 365 days a year.',
    '$5 per vehicle (2-8 people); $4 single-occupant vehicle; $2 pedestrians, bicyclists and extra passengers. Boat ramp $4 extra.',
    false,
    null,
    '{"alcohol":"Prohibited. Alcoholic beverages are not allowed in Florida state parks (F.A.C. 62D-2.014).","pets":"Pets are allowed on a 6-foot handheld leash on trails and in use areas but not in the swimming area; they may not be left unattended.","other":["Boat motors must be under 20 horsepower; overnight mooring is not permitted.","Canoe and kayak rentals are not available."]}'::jsonb,
    null,
    '02300018',
    9.8,
    '{"gridId":"TBW","gridX":78,"gridY":77,"forecast":"https://api.weather.gov/gridpoints/TBW/78,77/forecast","forecastHourly":"https://api.weather.gov/gridpoints/TBW/78,77/forecast/hourly"}'::jsonb,
    'FLZ255',
    'FLC081',
    null,
    false,
    'A lifeguard is not provided - swim at your own risk. The swimming area is on the shore of a human-made reservoir; water plants are often blown ashore and conditions and access vary by season, so the park strongly recommends calling 941-741-3028 before a visit for current conditions. Motorboats (under 20 hp) use the lake.',
    'https://www.floridastateparks.org/parks-and-trails/lake-manatee-state-park',
    null,
    '20007 State Road 64 East, Bradenton FL 34212 (941-741-3028). No day-use reservations. 94 parking spaces plus 18 boat-trailer spaces; parking is included in the entry fee and overnight parking is not allowed. Call ahead for swim-area conditions. Coordinates are the park centroid, not the swim area.',
    null,
    'A small park on three miles of Lake Manatee''s south shore, 15 miles east of Bradenton, with a designated swimming beach in the day-use area, a restroom with rinse station nearby and a large oak-shaded picnic area. Despite the name there are no manatees - a dam blocks them.'
)
