-- Mike Roess Gold Head Branch State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'mike-roess-gold-head-branch-state-park',
    'Mike Roess Gold Head Branch State Park',
    'lake',
    'state',
    29.83692,
    -81.95012,
    'basic',
    true,
    'no',
    '8 a.m. to sundown, 365 days a year.',
    '$5 per vehicle (up to 8 people); $4 single-occupant vehicle or motorcycle; $2 pedestrians, bicyclists and extra passengers. Canoe rental $4 per hour.',
    false,
    null,
    '{"alcohol":"Prohibited. Alcoholic beverages are not allowed in Florida state parks (F.A.C. 62D-2.014).","pets":"Pets are welcome on a 6-foot leash but are not allowed on the beach, in the swimming area, or in cabins and cabin areas.","other":["Swimming is allowed in the designated swimming area only."]}'::jsonb,
    null,
    null,
    null,
    '{"gridId":"JAX","gridX":57,"gridY":42,"forecast":"https://api.weather.gov/gridpoints/JAX/57,42/forecast","forecastHourly":"https://api.weather.gov/gridpoints/JAX/57,42/forecast/hourly"}'::jsonb,
    'FLZ232',
    'FLC019',
    null,
    false,
    'No lifeguard on duty - watch children and non-swimmers carefully. Swimming is allowed only in the designated area of Little Lake Johnson, a sandhill lake whose level rises and falls with rainfall: the official park notice says the swimming area is CLOSED effective July 6, 2026 because of low water, with no swimming permitted elsewhere in the park. Call 352-316-4286 for current water levels.',
    'https://www.floridastateparks.org/parks-and-trails/mike-roess-gold-head-branch-state-park',
    null,
    '6239 State Road 21, Keystone Heights FL 32656 (352-316-4286). No day-use reservations. The beach is downhill from the picnic area and an easy walk from the cabins but a longer walk from the campgrounds; the restroom by the swim area has no electricity or showers. Turkey Oak campground closed for renovation from March 2026. Coordinates are the park centroid, not the swim area.',
    null,
    'One of Florida''s first state parks, built by the CCC in the 1930s on rolling sandhills near Keystone Heights, with a large sandy beach on spring-fed Little Lake Johnson below the picnic area and lakefront cabins. The lake''s water level swings with drought, and the swim area has been closed for low water since July 2026.'
)
