-- O'Leno State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'oleno-state-park',
    'O''Leno State Park',
    'river',
    'state',
    29.91356,
    -82.57779,
    'basic',
    true,
    'no',
    '8 a.m. to sundown, 365 days a year.',
    '$5 per vehicle (2-8 people); $4 single-occupant vehicle; $2 pedestrians, bicyclists and extra passengers.',
    false,
    null,
    '{"alcohol":"Prohibited. Alcoholic beverages are not allowed in Florida state parks (F.A.C. 62D-2.014).","pets":"Well-behaved pets are welcome under the Florida State Parks pet policy (6-foot leash) but not in the swimming area (statewide rule).","other":["Canoeing downriver from the in-park launch is prohibited because of the swimming area and the River Sink; paddle upstream and return."]}'::jsonb,
    null,
    '02321898',
    2.3,
    '{"gridId":"JAX","gridX":33,"gridY":43,"forecast":"https://api.weather.gov/gridpoints/JAX/33,43/forecast","forecastHourly":"https://api.weather.gov/gridpoints/JAX/33,43/forecast/hourly"}'::jsonb,
    'FLZ522',
    'FLC023',
    null,
    false,
    'No lifeguard on duty - swim at your own risk. The swim area is on the tea-coloured Santa Fe River just above the River Sink, where the river disappears underground; it is closed for safety when the river is too high or too low, so call 386-454-1853 before you come. Paddling downstream past the swim area toward the sink is prohibited.',
    'https://www.floridastateparks.org/parks-and-trails/oleno-state-park',
    null,
    '410 SE O''Leno Park Road, High Springs FL 32643 (386-454-1853), on US 441 six miles north of High Springs. No day-use reservations. The River Trail is closed effective May 14, 2026. Coordinates are the park centroid, not the swim area.',
    null,
    'A 1930s CCC-built park on the Santa Fe River north of High Springs, with a river swimming area, a historic suspension bridge, riverside pavilions and shaded trails where the river vanishes into a sinkhole. Swimming depends on river level and closes when the water is too high or too low.'
)
