-- Ochlockonee River State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'ochlockonee-river-state-park',
    'Ochlockonee River State Park',
    'river',
    'state',
    30.00344,
    -84.48625,
    'basic',
    true,
    'unknown',
    '8 a.m. to sunset, 365 days a year.',
    '$4 per vehicle (up to 8 people); $2 each additional person; $2 pedestrian or bicyclist. Boat launch $4.',
    false,
    null,
    '{"alcohol":"Prohibited. Alcoholic beverages are not allowed in Florida state parks (F.A.C. 62D-2.014).","pets":"Pets are allowed under the Florida State Parks pet policy (6-foot leash) but not in the swimming area (statewide rule).","other":[]}'::jsonb,
    null,
    '02327100',
    14,
    '{"gridId":"TAE","gridX":78,"gridY":67,"forecast":"https://api.weather.gov/gridpoints/TAE/78,67/forecast","forecastHourly":"https://api.weather.gov/gridpoints/TAE/78,67/forecast/hourly"}'::jsonb,
    'FLZ127',
    'FLC129',
    null,
    false,
    'The swimming area is on the Dead River near its junction with the tidal Ochlockonee River, so expect dark water, current and boat traffic from the nearby ramp. No lifeguard is mentioned on the official page - treat it as unguarded.',
    'https://www.floridastateparks.org/parks-and-trails/ochlockonee-river-state-park',
    '/photos/basic/ochlockonee-river-state-park.jpg',
    '429 State Park Road, Sopchoppy FL 32358 (850-962-2771), off US 319 south of Sopchoppy. No day-use reservations. Pavilions are first-come unless reserved. Coordinates are the park centroid, not the swim area.',
    null,
    'A quiet longleaf-pine park near Sopchoppy where the Ochlockonee and Dead rivers meet, with a small swimming area, outdoor showers and pavilions in the day-use area beside an accessible boat ramp and kayak launch.'
)
