-- Oscar Scherer State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'oscar-scherer-state-park',
    'Oscar Scherer State Park',
    'lake',
    'state',
    27.18073,
    -82.46023,
    'basic',
    true,
    'unknown',
    '8 a.m. to sundown, 365 days a year. Nature center open Saturday and Sunday 10 a.m. to 2 p.m.',
    '$5 per vehicle (up to 8 people); $4 single-occupant vehicle; $2 pedestrians, bicyclists and extra passengers. Sunset entry (last hour before sunset) $4 per vehicle.',
    false,
    null,
    '{"alcohol":"Prohibited except in designated areas during park-sanctioned events.","pets":"Pets are allowed on a 6-foot handheld leash in the campground and recreation areas but by law not on the swimming beach or in the lake, nor in restrooms, on playgrounds or in rental canoes.","other":["Fishing is not permitted inside the roped-off swimming area.","Snorkeling is allowed in Lake Osprey."]}'::jsonb,
    null,
    '02298880',
    10.4,
    '{"gridId":"TBW","gridX":74,"gridY":64,"forecast":"https://api.weather.gov/gridpoints/TBW/74,64/forecast","forecastHourly":"https://api.weather.gov/gridpoints/TBW/74,64/forecast/hourly"}'::jsonb,
    'FLZ160',
    'FLC115',
    null,
    false,
    'Lake Osprey is a small freshwater lake with a roped-off swimming area; the official page does not mention a lifeguard, so treat it as unguarded. Fishing is allowed on the lake but not inside the swim ropes. Cold-water showers only at the beach bathhouse.',
    'https://www.floridastateparks.org/parks-and-trails/oscar-scherer-state-park',
    '/photos/basic/oscar-scherer-state-park.jpg',
    '1843 S. Tamiami Trail (US 41), Osprey FL 34229 (941-483-5956). No day-use reservations. Swimming is at the Lake Osprey Picnic Area, which has its own parking, bathhouse and playground. Coordinates are the park centroid, not the swim area.',
    null,
    'A scrub-jay preserve tucked between Sarasota-area suburbs, with Lake Osprey - the only freshwater swimming lake in Sarasota County - offering a sandy beach, roped swim area, snorkeling, bathhouse and pavilions beside a nature center. The paved Legacy Trail runs through the park.'
)
