-- Ponce de Leon Springs State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'ponce-de-leon-springs-state-park',
    'Ponce de Leon Springs State Park',
    'spring',
    'state',
    30.70884,
    -85.92743,
    'basic',
    true,
    'unknown',
    '8 a.m. to sunset, 365 days a year.',
    '$4 per vehicle (up to 8 people), paid at the honor box - correct change required; $2 pedestrians, bicyclists and extra passengers. Picnic pavilions $25 plus tax (first-come, first-served May 26 - Sept. 1).',
    false,
    null,
    '{"alcohol":"Prohibited in all areas of the park, including picnic pavilions and the beach.","pets":"Pets are allowed in designated areas under the Florida State Parks pet policy but not in the spring or swim area.","other":["Fishing is permitted only outside the designated swimming area.","Snorkeling is allowed in designated areas only."]}'::jsonb,
    null,
    '02365500',
    12.1,
    '{"gridId":"TAE","gridX":21,"gridY":94,"forecast":"https://api.weather.gov/gridpoints/TAE/21,94/forecast","forecastHourly":"https://api.weather.gov/gridpoints/TAE/21,94/forecast/hourly"}'::jsonb,
    'FLZ009',
    'FLC059',
    null,
    false,
    'The spring stays a constant 68 F year-round - cold enough to tire swimmers. Swim and snorkel only in the designated areas; fishing is kept out of the swim area. The park frequently reaches capacity in summer and closes its gates for unknown periods; pedestrians and cyclists are not admitted while it is closed.',
    'https://www.floridastateparks.org/parks-and-trails/ponce-de-leon-springs-state-park',
    null,
    '2860 Ponce de Leon Springs Road, Ponce de Leon FL 32455 (850-836-4281), just off I-10 exit 96. No day-use reservations; pay at the honor box. During busy periods expect long waits - the park frequently hits capacity and temporarily closes, with admission reopening periodically through the day. Pavilion reservations do not guarantee entry. Coordinates are the park centroid, not the swim area.',
    null,
    'A clear 68 F spring in the western Panhandle, fed by two underground flows that pump 14 million gallons a day into a short run that meets tea-coloured Sandy Creek. A large bathhouse with changing rooms, pavilions and two short nature trails surround the swim area.'
)
