-- Wes Skiles Peacock Springs State Park
insert into public.parks ("slug", "name", "type", "operator", "lat", "lng", "coverage_tier", "swimming_verified", "guarded", "hours", "fees", "reservation_required", "reservation_url", "rules", "usgs_site_id", "river_gauge_site_id", "gauge_distance_km", "nws_grid", "nws_zone", "nws_county", "typical_closure_time", "cavern_warning", "safety_notes", "official_url", "photo_url", "entrance_notes", "swim_season", "description")
values (
    'wes-skiles-peacock-springs-state-park',
    'Wes Skiles Peacock Springs State Park',
    'spring',
    'state',
    30.13162,
    -83.13637,
    'basic',
    true,
    'no',
    '8 a.m. to sundown, 365 days a year. Dives must end one hour before sundown.',
    '$4 per vehicle (up to 8 people), paid at the honor box - correct change required; $2 pedestrians, bicyclists and extra passengers.',
    false,
    null,
    '{"alcohol":"Prohibited. Alcoholic beverages are not allowed in Florida state parks (F.A.C. 62D-2.014).","pets":"Well-behaved dogs are welcome on a 6-foot handheld leash and may not be left unattended more than 30 minutes; dogs are not permitted in the springs.","other":["Divers must show proof of certification, sign in, and dive in teams of at least two; no solo diving, no DPVs (scooters).","Cave and cavern diving only in Orange Grove Sink and Peacock Springs; open-water divers only in Orange Grove Sink and may not carry lights.","Dives must be concluded one hour before sundown."]}'::jsonb,
    null,
    '02320000',
    4.9,
    '{"gridId":"JAX","gridX":11,"gridY":51,"forecast":"https://api.weather.gov/gridpoints/JAX/11,51/forecast","forecastHourly":"https://api.weather.gov/gridpoints/JAX/11,51/forecast/hourly"}'::jsonb,
    'FLZ021',
    'FLC121',
    null,
    true,
    'No lifeguard on duty - swim at your own risk. Swimming and snorkeling are allowed only in Peacock Springs and Orange Grove Sink and depend on seasonal water levels. These springs open into one of the longest underwater cave systems in the country (nearly 33,000 feet surveyed): only certified cave and cavern divers may enter the caves, in teams of two or more, and open-water divers are limited to Orange Grove Sink without lights. No potable water in the park.',
    'https://www.floridastateparks.org/parks-and-trails/wes-skiles-peacock-springs-state-park',
    '/photos/basic/wes-skiles-peacock-springs-state-park.jpg',
    '18532 180th Street, Live Oak FL 32060 (386-294-3667). No reservations; pay at the honor box. Two parking areas, each with a portable restroom and changing room; facilities are limited and there is no drinking water. Coordinates are the park centroid, not the swim area.',
    null,
    'A quiet Suwannee County park with two major springs, a spring run and six sinkholes over one of the longest underwater cave systems in the United States. Swimming in Peacock Springs and Orange Grove Sink is popular in summer, and a shaded interpretive trail traces the caves below.'
)
