-- ---------------------------------------------------------------- accessibility
delete from public.accessibility where park_id in (select id from public.parks where slug in ('ichetucknee-springs-state-park', 'ginnie-springs', 'poe-springs-park', 'gilchrist-blue-springs-state-park', 'rainbow-springs-state-park', 'blue-spring-state-park', 'wekiwa-springs-state-park', 'madison-blue-spring-state-park', 'lafayette-blue-springs-state-park', 'troy-spring-state-park', 'fanning-springs-state-park', 'manatee-springs-state-park', 'de-leon-springs-state-park', 'weeki-wachee-springs-state-park', 'kelly-park-rock-springs', 'hart-springs-park', 'lithia-springs-conservation-park', 'hunter-springs-park', 'little-river-springs-park', 'royal-springs-park', 'suwannee-springs-park', 'otter-springs-park', 'morrison-springs-park', 'vortex-spring', 'williford-spring', 'pitt-spring-recreation-area', 'cypress-spring', 'alfred-b-maclay-gardens-state-park', 'blackwater-river-state-park', 'edward-ball-wakulla-springs-state-park', 'falling-waters-state-park', 'florida-caverns-state-park', 'lake-louisa-state-park', 'lake-manatee-state-park', 'mike-roess-gold-head-branch-state-park', 'oleno-state-park', 'ochlockonee-river-state-park', 'oscar-scherer-state-park', 'ponce-de-leon-springs-state-park', 'wes-skiles-peacock-springs-state-park'));
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'ichetucknee-springs-state-park'), 'limited', 'other', null, null, true, 'paved', null, true, null, 'Head Spring: one staff/volunteer-assisted chair lift plus a staircase with handrails; stairs may be slippery. Blue Hole: staircase with handrails, deep with strong current (strong swimmers only). Dampier''s Landing (tubing): 0.25-mile paved trail and ramp to the water''s edge, rocky sloped entry. South Takeout: paved ramp and concrete stairway with handrails in the water; wheelchair-accessible tram carries wheelchairs to the takeout.', 'Service animals are not allowed in the swimming areas or on tubes (official).', true, 'Official accessible-features page (all restrooms have at least one ADA stall; wheelchair-accessible picnic pads; no ADA parking count or loaner chair published).');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'ginnie-springs'), 'unknown', 'stairs', null, null, null, 'boardwalk', null, true, null, 'Each spring has sun decks and sturdy stairs with railings into the water (facilities page). No statement about wheelchair water entry.', 'No pets allowed; the park publishes no service-animal statement.', false, 'Inferred from ginniespringsoutdoors.com facilities page - no ADA parking, accessible-restroom or wheelchair statements (the site''s /accessibility/ page is a website WCAG statement, not park access).');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'poe-springs-park'), 'unknown', 'unknown', null, null, null, 'unknown', null, null, null, 'Not published. (Photos show concrete steps with a handrail into the spring pool - unverified.)', 'Not published; county ADA coordinator: ADA@alachuacounty.us, 352-374-5275.', false, 'Alachua County park page lists pavilions, restrooms, boardwalk, boat launch and an ADA coordinator contact only - no on-site accessibility details.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'gilchrist-blue-springs-state-park'), 'unknown', 'unknown', null, null, null, 'unknown', null, null, null, 'Not published. Swim entrance, launch and bathrooms are being rebuilt (no water activities since Oct 29, 2025); a third-party summary says the renovation includes an ADA path to the springhead - unverified. Port-o-lets only until renovations finish.', 'Service animals are welcome (official accessible-amenities list).', false, 'Official experiences-amenities page lists accessible concession, picnic facilities and campsites only - no water-entry, ADA parking or restroom statements.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'rainbow-springs-state-park'), 'unknown', 'unknown', null, null, null, 'paved', true, null, null, 'Swim area is 10-18 ft deep with no shallow end. The park does not describe how wheelchair users enter the water. Pathways were built before ADA guidelines and are steep and uneven in places (brick, concrete and asphalt).', 'Pets are not permitted in swimming areas; no separate service-animal statement on the park page (system policy excludes service animals from swimming areas).', true, 'Official experiences-amenities page: a wheelchair is available in the gift shop first-come, first-served (driver''s licence deposit); campground has ADA restrooms; headsprings restroom accessibility and ADA parking count not published.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'blue-spring-state-park'), 'unknown', 'unknown', null, null, true, 'boardwalk', null, null, null, 'An accessible boardwalk leads to the spring (official). The park does not describe the swim-dock entry (stairs/ramp/lift) for wheelchair users. Boat tours have a wheelchair lift into the vessel.', 'Pets including service animals are prohibited on the water (official).', true, 'Official experiences-amenities page: accessible boardwalk to Blue Spring, two bathhouses with accessible showers and stalls, accessible picnic pavilions, cabins and campsites; water-entry method, ADA parking count and loaner chairs not published.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'wekiwa-springs-state-park'), 'yes', 'ramp', null, null, null, 'unknown', null, null, null, 'Ramp for spring entry plus a hydraulic swim lift rated to 400 lb, usable alone or with a companion (tell park staff at entry if you want help). The seat can stay in the water until you are ready to get out. Swim area is shallow: under 1 ft to about 5 ft. Two accessible restrooms with showers are in the campground; spring-area restroom accessibility is not stated.', 'Service animals are welcome in all areas of the park except swimming areas (official).', true, 'Official experiences-amenities page, ''Accessible Amenities'': chair lift for spring entry, ramp for spring entry, four accessible campsites; ADA nature center and boardwalk trail.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'madison-blue-spring-state-park'), 'unknown', 'unknown', null, null, true, 'unknown', null, null, null, 'The park does not describe how a wheelchair user gets into the water. The swim area has wading sections less than 5 ft deep and sections reaching about 25 ft; climbing on or jumping from the limestone walls is prohibited. Only temporary restrooms are on site - no bathhouse or changing area.', 'Service animals are welcome in all areas of Florida State Parks, but not in any of the swimming areas: the spring and adjacent river are public bathing places under Department of Health rules, and alligators are drawn to animals (official).', true, 'Official experiences-amenities page, ''Accessible Amenities'': restrooms and picnic facilities are accessible; service animals welcome. Water-entry method, ADA parking count, loaner chairs and path surfaces are not published.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'lafayette-blue-springs-state-park'), 'unknown', 'ramp', null, null, null, 'unknown', null, null, null, 'A walkway ramp leads to the spring and the river (official accessible-amenities list), but the park does not say whether a wheelchair user can get into the water. A cold-water, open-air rinse station is in the spring area. Swimming closes when the Suwannee River floods the spring.', 'Service animals are welcome in all areas of Florida State Parks; systemwide policy excludes animals from swimming areas.', true, 'Official experiences-amenities page, ''Accessible Amenities'': walkway ramp to the spring and river, accessible picnic facilities, one accessible modern cabin with an elevator, interpretive exhibits; paved day-use parking. Restroom accessibility, ADA parking count and the water-entry method are not published.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'troy-spring-state-park'), 'unknown', 'ramp', null, null, true, 'paved', null, null, null, 'A long, paved, switchback ramp provides access to the spring dock (official, described in the diving section) and the park lists an accessible walkway to the spring. How a wheelchair user enters the water from the dock is not described; the spring is 70 ft deep with shallow areas in the spring run.', 'Service animals are allowed in all areas of the park (official); systemwide policy excludes animals from swimming areas.', true, 'Official experiences-amenities page: accessible walkway to the spring, accessible picnic facilities, accessible restroom facilities and accessible water fountains; a long paved switchback ramp runs to the spring dock. ADA parking count, loaner chairs and the water-entry method are not published.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'fanning-springs-state-park'), 'limited', 'ramp', null, null, true, 'boardwalk', null, null, null, 'Official accessible amenities include ''transition steps and accessibility ramp at the spring''. Swimmers can wade in from the shore or the dock and toddlers can stay in a shallow area; water is 72 degrees year-round. Effective Aug. 20, 2026 the floating dock is under an improvement project and visitors may be asked to exit the water at any time.', 'Service animals are welcome in all areas of Florida State Parks; systemwide policy excludes animals from swimming areas.', true, 'Official experiences-amenities page, ''Accessible Amenities'': transition steps and accessibility ramp at the spring, accessible picnic facilities, ADA-accessible cabin; the restroom nearest the river campsite is described as accessible. ADA parking count and loaner chairs are not published.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'manatee-springs-state-park'), 'unknown', 'unknown', null, null, true, 'boardwalk', null, null, null, 'An 800-foot boardwalk runs through the cypress forest to the spring, but the park does not describe how a wheelchair user enters the water. The current in the spring run is swift and swimming is prohibited in the run, at the end of the boardwalk and in Catfish Hotel.', 'Service animals are welcome in all areas of Florida State Parks; dogs are not permitted in the swimming area or on the boardwalks.', true, 'Official experiences-amenities page: ADA-accessible restrooms and showers in the Magnolia 1 and Hickory camping loops and an ADA restroom at the waterfront (the waterfront restroom has been closed since Jan. 14, 2026); accessible amphitheater, concession, campsites and picnic facilities. Water-entry method and ADA parking count are not published.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'de-leon-springs-state-park'), 'limited', 'other', true, null, true, 'paved', true, true, null, 'Swimmer chair lift upon request plus stairs with handrails into the swimming area (official). The swim area is a constant 72 degrees and ranges from 18 inches deep to 30 feet at the spring boil; it closes when lightning is detected within 6 miles. Sidewalks and boardwalks reach all facilities and the half-mile paved nature trail is wheelchair accessible.', 'Service animals are allowed in all areas of the park (official); pets are not allowed in the sunbathing area.', true, 'Official experiences-amenities page, ''Accessible Amenities'': swimmer chair lift upon request and stairs with handrails into the swimming area, wheelchair available upon request (an all-terrain wheelchair at the ranger station), accessible restrooms, sidewalks and boardwalks to all facilities, accessible parking near all facilities, paved nature trail, accessible boat tour and fishing pier. The number of ADA spaces is not published.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'weeki-wachee-springs-state-park'), 'yes', 'sand', true, null, true, 'paved', true, null, null, 'Buccaneer Bay is a white sand beach with a shallow entry area, and a wheeled assistive chair with side floats is available to help guests into the water (official accessibility page). Staff assistance is available for tubing; tubes are open-bottom with no enclosed seat. Docks are floating and have no railings. Water slides close at 4:30 p.m. and swimming at 5 p.m.', 'No published service-animal statement; pets are not permitted in the park. Florida State Parks welcomes service animals systemwide but excludes them from swimming areas.', true, 'Official park accessibility page published by concessionaire Guest Services: 10 accessible parking spaces about 20 yards from the entrance, level cement walkways, ADA restroom stalls with rails near the Mermaid Galley and the Gift Locker building, shallow-entry swim area with a wheeled assistive chair, ADA-compliant kayak launch, wheelchair-accessible Mermaid Theater. Buccaneer Bay is on portable toilets while a new restroom building is built, and the distance from parking to the water is not published.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'kelly-park-rock-springs'), 'unknown', 'unknown', null, null, null, 'unknown', null, null, null, 'Not published. Rock Springs is a free-flowing natural spring run at a constant 68 degrees; the county does not describe entry steps, ramps or depths. The swim area closes one hour before the park and whenever a storm produces lightning.', 'With the exception of ADA service animals, pets are not allowed in Kelly Park (official).', false, 'Orange County park page publishes hours, fees, capacity, camping and launch rules only - no accessibility details for the spring run, restrooms, paths or parking. Its only ADA statement is that service animals are exempt from the no-pets rule.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'hart-springs-park'), 'limited', 'stairs', true, null, true, 'boardwalk', null, true, true, 'The swimming area is entered from a bulkhead and steps; it is one of the largest spring-fed swim areas in Florida and gets deep away from the edge. A half-mile boardwalk follows the spring run to the Suwannee River and is described as wheelchair-friendly. No published depth at the entry point and no chair lift.', 'Pets are banned from the day-use springs area; the park does not publish a service-animal policy, so call (352) 463-3444 before relying on one.', false, 'Gilchrist County does not publish an accessibility page. Accessible parking, entrance, restrooms and the wheelchair-friendly boardwalk are reported by third-party guides (VisitFloridaSprings, Florida Birding Trail), not by the park.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'lithia-springs-conservation-park'), 'unknown', 'unknown', null, null, null, 'natural', null, null, true, 'The fenced swim area has a shallow end where inflatable rings and toys are allowed and a roped deep end where no flotation devices are permitted. Hillsborough County does not publish depths or an accessible entry route into the spring.', 'Hillsborough County states that pets and service animals are not permitted inside the spring area (official). Service animals are otherwise allowed in the park.', false, 'Hillsborough County publishes no accessibility detail for the spring beyond the service-animal restriction; the park map and brochure PDFs do not describe an accessible entry. Call (813) 744-5572.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'hunter-springs-park'), 'limited', 'sand', null, null, null, 'boardwalk', null, null, true, 'A small sand beach slopes into a roped-off swim area on Kings Bay; the spring vent is about 100 feet offshore and the bottom drops away past the ropes. The city does not publish an accessible beach route or a beach wheelchair.', 'No dogs or pets in the park; service animals are permitted under Titles II and III of the ADA (official).', false, 'City of Crystal River park page lists amenities and rules but no accessibility features. Call the park ranger on 352-697-0933.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'little-river-springs-park'), 'limited', 'stairs', null, null, false, 'paved', null, null, true, 'Paved parking and paved sidewalks lead to two overlook decks above the spring; getting into the water is by the bank and steps, and the pool drops off steeply toward the cave mouth. No published depth at the entry point.', 'No pets allowed; the county does not publish a service-animal policy. Restrooms are portable units, so an accessible stall is not assured.', true, 'Suwannee County Parks & Recreation states three handicap-accessible pavilion areas, paved parking and paved sidewalks; restrooms are portable.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'royal-springs-park'), 'limited', 'stairs', null, null, false, 'natural', null, null, true, 'Two sets of stairs lead into the spring and there is a jumping platform above the boil, which is deep. The county publishes no accessible route to the water and no depths.', 'No pets allowed; the county does not publish a service-animal policy. Restrooms are portable units.', false, 'Suwannee County Parks & Recreation lists stairs, a diving/jumping platform, a pavilion and portable restrooms, but no accessibility features.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'suwannee-springs-park'), 'limited', 'other', null, null, null, 'natural', null, null, true, 'Entry is over the uneven limestone of an 1800s spring house and down the natural river bank to the sand bars. No steps, ramp, handrail or accessible route is published, and the walls are slick.', 'Dogs are allowed on District lands on a leash; no specific service-animal policy is published.', false, 'Suwannee River Water Management District tract page lists a picnic area, restrooms and a canoe launch but publishes no accessibility detail. Call 386.362.1001.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'otter-springs-park'), 'unknown', 'unknown', null, null, null, 'unknown', null, null, true, 'The county publishes nothing about how you get into the spring in the picnic area, or about the pool''s entry. The pool is heated in winter and may be the more predictable option for someone who needs a rail or a ladder.', 'No pet or service-animal policy is published for the day-use area.', false, 'Gilchrist County resumed management of the park in February 2026 and has not published accessibility information. Call (352) 463-0800.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'morrison-springs-park'), 'limited', 'sand', true, null, null, 'boardwalk', null, null, true, 'Wheelchair-accessible boardwalks and ramps run to the diver''s dock and to the beach area, so you can get to the water''s edge; the last step into the spring is over the sand beach. The pool itself is deep, with cavern openings and a cavity reaching about 300 feet.', 'Walton County publishes no pet or service-animal policy for the park.', true, 'Walton County Amenities page states wheelchair-accessible boardwalks and ramps to the diver''s dock and beach area, and handicapped parking near the pavilions.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'vortex-spring'), 'unknown', 'stairs', null, null, null, 'unknown', null, null, true, 'The basin is entered from decks, docks, platforms and a slide; the operator publishes no accessible entry route or depths, and everyone signs a waiver before swimming.', 'Qualifying service animals are permitted anywhere guests may go; other pets are limited to designated campground areas (official).', false, 'Vortex Spring Adventures publishes rules and a pet/service-animal policy but no accessibility information. Call the dive shop on (850) 836-4979.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'williford-spring'), 'limited', 'stairs', null, null, false, 'boardwalk', null, true, true, 'A boardwalk system rings the spring and runs out to Econfina Creek, and entry steps with handrails lead down into the spring. The boil is deeper than it looks; no depths are published. Toilets are composting units, so an accessible stall is not assured.', 'The District publishes no service-animal policy for this site; dogs are generally allowed on District lands under control.', true, 'Northwest Florida Water Management District site page lists mobility access, the boardwalk system and entry steps with handrails into the spring.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'pitt-spring-recreation-area'), 'limited', 'other', null, null, false, 'boardwalk', null, true, true, 'An extensive trail and boardwalk system links the springs, and the swimming area has safety railings; tube put-in and take-out docks sit at either end of the run. The District does not publish an accessible route into the water or any depths. Toilets are composting units.', 'The District publishes no service-animal policy for this site; dogs are generally allowed on District lands under control.', false, 'Northwest Florida Water Management District site page lists boardwalks, docks and a railed swimming area; ''mobility'' access is listed for the Econfina Creek area as a whole but not specifically for this site.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'cypress-spring'), 'no', 'other', false, null, false, 'natural', null, null, true, 'There is no road access and no facilities: you arrive by kayak, canoe or boat on Holmes Creek and get in from the vessel or the natural bank. The District''s 2026 restoration project is adding boardwalks and steps at the entry and exit points, but until that is finished there is no built entry at all.', 'No service-animal policy is published; there is no staffed entrance.', false, 'Northwest Florida Water Management District describes Holmes Creek access as primarily by boat and has an open shoreline-restoration project at the spring; no accessibility information is published.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'alfred-b-maclay-gardens-state-park'), 'unknown', 'unknown', null, null, null, 'unknown', null, null, null, null, 'Working service animals are welcome anywhere in the park, including the formal gardens.', false, 'Official park page states service animals are welcome anywhere; the Experiences & Amenities sub-page was not reachable (404) so water entry, restrooms and parking are unverified.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'blackwater-river-state-park'), 'limited', 'sand', null, null, true, 'boardwalk', null, null, null, 'A boardwalk runs from the pavilion parking lot to the restrooms, picnic area and main swimming beach; the park lists ''access to beach and river'' and an outdoor shower among its accessible amenities. Entry into the water is from a sand beach on a river with current.', 'Service animals are welcome in all areas of Florida State Parks.', true, 'Official Experiences & Amenities page (Accessible Amenities, Swimming): boardwalk from pavilion parking to restrooms/picnic area, access to beach and river, outdoor shower, accessible campsites and pavilion grills/tables. Beach wheelchair, ADA parking count and handrails not stated; call 850-983-5363.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'edward-ball-wakulla-springs-state-park'), 'limited', 'other', null, null, null, 'unknown', true, null, true, 'An amphibious mobility-assist vehicle (beach wheelchair) is available on request at the waterfront visitor center for getting to and into the water; a manual wheelchair can also be borrowed. Swim entry is otherwise from the grassy beach and the platform stairs. Shade from cypress trees along the beach.', null, true, 'Official Experiences & Amenities page (Accessible Amenities, Swimming, Beach): manual wheelchair, amphibious mobility assist vehicle, wheelchair-friendly river boats, accessible picnic shelters and benches. Restroom accessibility and parking distance not stated.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'falling-waters-state-park'), 'unknown', 'sand', null, null, true, 'unknown', null, null, null, 'Entry is from a white sand beach into a small lake; the official page does not describe an accessible water entry.', null, true, 'Official Experiences & Amenities page: ADA-accessible restrooms at the lake and picnic area; pavilions near an accessible restroom. Sand beach entry from the Swimming section. Loaner chairs, parking distance and water access not stated.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'florida-caverns-state-park'), 'unknown', 'unknown', null, null, null, 'unknown', null, null, null, 'Blue Hole swimming area is about 35 feet deep. The official page does not describe the water entry.', 'Service animals are welcome in all areas of Florida State Parks.', false, 'Official Experiences & Amenities page lists accessible visitor center/museum (with a video of the cave tour), gift shop and picnic facilities; it does not describe accessible water entry, restrooms or parking.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'lake-louisa-state-park'), 'unknown', 'sand', null, null, null, 'paved', null, null, true, 'Swim entry is from the Lake Louisa beach; the official page does not describe an accessible water entry. A sidewalk connects the fully accessible playground to the beach bathhouse, and picnic tables sit under shade oaks.', 'Service animals are welcome in all areas of the park; tell staff on arrival at cabins.', true, 'Official Experiences & Amenities page: fully accessible playground connected by sidewalk to the Lake Louisa bathhouse; accessible bathhouses and fishing piers in the campground and accessible pavilion at Dixie Lake. Whether the beach bathhouse restroom itself is accessible, ADA parking and water entry are not stated.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'lake-manatee-state-park'), 'unknown', 'sand', true, null, true, 'unknown', null, null, null, 'Swim entry is from a beach on the reservoir shore; the park says accessibility of the swimming area varies seasonally and asks visitors to call ahead. A rinse station is at the restroom by the swim area.', 'Service animals are welcome in all visitor use areas of the park.', true, 'Official Experiences & Amenities page (Accessible Amenities): accessible parking, restrooms (ADA), playground, picnic facilities and campsites; swim-area access ''varies seasonally''. Loaner chairs, handrails and parking distance not stated.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'mike-roess-gold-head-branch-state-park'), 'unknown', 'sand', null, null, null, 'unknown', null, null, null, 'Large sandy beach downhill from the picnic area; the official page does not describe an accessible route or water entry. The restroom near the swim area has no electricity or showers.', 'Service animals are welcome in all areas of Florida State Parks.', false, 'Official Experiences & Amenities page lists only accessible picnic facilities, campsites and modern cabins; no accessible beach access, restroom, parking or loaner chair statement.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'oleno-state-park'), 'limited', 'other', null, null, null, 'unknown', true, null, true, 'A beach wheelchair is available (ask at the ranger station). The swim area is a river bank on the Santa Fe; the official page does not describe the entry itself.', null, true, 'Official Experiences & Amenities page (Accessible Amenities): beach wheelchair, accessible campsites, accessible cabin and dining hall in the group camp, ramp access to a picnic pavilion. Restrooms, parking and water entry not described.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'ochlockonee-river-state-park'), 'limited', 'other', null, null, null, 'paved', true, null, null, 'A beach wheelchair is available. Two of the four day-use pavilions are reached by paved sidewalks from the parking area, and there is an accessible outdoor shower at the Dead River pavilion. The water entry itself is not described.', null, true, 'Official Experiences & Amenities page (Accessible Amenities): beach wheelchair, accessible picnic pavilion, fishing/observation dock, boat ramp and dock, kayak launch, outdoor shower and water fountain, accessible campsites; paved sidewalks to two pavilions. Restroom accessibility and ADA parking not stated.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'oscar-scherer-state-park'), 'limited', 'sand', null, null, true, 'unknown', null, null, null, 'The park lists ''lake beach access'' among its accessible amenities, plus an ADA-accessible pavilion (No. 4) at the Lake Osprey beach; the entry itself is a sandy beach. Beach bathhouse has cold-water showers.', 'Service animals are allowed in all public areas and buildings of the park.', true, 'Official Experiences & Amenities page (Accessible Amenities): lake beach access, accessible campsites and restrooms, Lester Finley Barrier Free Trail, Lake Osprey Trail, fishing dock, canoe/kayak launch, nature center, playground, tram tours, listening devices, captioned videos. ADA parking, loaner chairs and handrails not stated.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'ponce-de-leon-springs-state-park'), 'limited', 'other', null, null, true, 'unknown', null, null, null, 'A chair lift at the spring lowers visitors into the water; call the park at 850-836-4281 ahead of your visit to arrange its use.', 'Service animals are welcome in all areas of Florida State Parks.', true, 'Official Experiences & Amenities page (Accessible Amenities): chair lift at the spring (call ahead), restrooms with a spacious changing area, accessible picnic facilities. Parking distance and loaner wheelchairs not stated.');
insert into public.accessibility ("park_id", "water_access", "entry_type", "ada_parking", "parking_to_water_m", "accessible_restroom", "surface", "wheelchair_loaner", "handrails", "shade", "depth_at_entry_note", "service_animals_note", "verified", "source")
values ((select id from public.parks where slug = 'wes-skiles-peacock-springs-state-park'), 'unknown', 'unknown', null, null, null, 'unknown', null, null, true, 'The official page does not describe the water entry. Facilities are limited: a portable restroom and changing room at each parking area, no potable water.', 'Service animals are welcome in all areas of Florida State Parks.', false, 'Official Experiences & Amenities page lists only accessible picnic facilities and interpretive exhibits; no accessible water entry, restroom or parking statement. Shade noted from the well-shaded trail and forest.');

