values ((select id from public.parks where slug = 'ichetucknee-springs-state-park'), 'North Entrance lot (Head Spring & Blue Hole swimming)', 29.9838, -82.7598, 'Included in park entry ($6 per vehicle)', null, null, false, 'curated', 'Approximate location near 8294 SW Elim Church Rd. Often reaches capacity on hot summer weekends and holidays, at which time the gate temporarily closes. No roadside waiting - law enforcement issues citations. ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'ichetucknee-springs-state-park'), 'South Entrance lot (Dampier''s Landing tubing)', 29.95557, -82.77201, 'Included in park entry ($6 per vehicle)', null, null, false, 'curated', 'OSM parking way 174751914 near 12087 SW US Hwy 27. Tubing only - no swimming from this entrance. Fills early on summer weekends; wheelchair-accessible tram runs to the takeout. No roadside waiting - citations issued.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
