insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'ginnie-springs'), 'Day-guest overflow lots', 29.8335, -82.6992, 'Included in per-person admission', null, null, true, 'curated', 'Approximate location near the entrance road. Day guests are directed to overflow lots on busy summer weekends; expect a walk to the springs.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'poe-springs-park'), 'Main lot near the spring and lodge', 29.8262, -82.6498, '$6 per vehicle May-Sep; free Oct-Mar', null, null, false, 'curated', 'Approximate location near 28800 NW 182nd Ave. Spring capacity is 100 people, so the park can close before the lot is full. Swim area closed since Jul 16, 2026. ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'gilchrist-blue-springs-state-park'), 'Main day-use lot', 29.8288, -82.6846, 'Included in park entry ($6 per vehicle)', null, null, false, 'curated', 'Approximate location near 7450 NE 60th St. On busy weekends the gate closes at capacity and day visitors are not readmitted until the next morning (visitor reports). Lot layout may change with the current renovations. ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'rainbow-springs-state-park'), 'Headsprings (swimming) entrance lot', 29.10513, -82.43883, 'Included in park entry ($5 per vehicle); day-use reservation required', null, null, false, 'curated', 'OSM parking way 457781954 near 19158 SW 81st Place Rd. Under renovation Sep 9, 2026 - Feb 4, 2027 with limited parking. When the headsprings reach capacity the park closes and vehicles may not wait in line on adjacent roads. News reports cite roughly 250 vehicles per day (estimate). ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'rainbow-springs-state-park'), 'Tubing entrance lot (seasonal)', 29.0782, -82.4331, 'Included in park entry; tube/shuttle fees extra', null, null, false, 'curated', 'Approximate location near 10830 SW 180th Ave Rd. Separate entrance for tubing only - no swimming. Open daily Memorial Day-Labor Day, weekends in spring and September, closed Oct-Mar.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'blue-spring-state-park'), 'Main day-use lot (swim area & concession)', 28.94441, -81.33797, 'Included in park entry ($6 per vehicle); day-use reservation required', null, null, false, 'curated', 'OSM parking way 229078670. Park frequently reaches capacity and may close for several hours; campers and boat-tour guests are still admitted. News reports cite about 232 vehicle slots per day (estimate). ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'blue-spring-state-park'), 'Second day-use lot (picnic area)', 28.9425, -81.34039, 'Included in park entry ($6 per vehicle); day-use reservation required', null, null, true, 'curated', 'OSM parking way 229078671 (access=yes, surface lot). Approximate role - used once the main lot fills.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'wekiwa-springs-state-park'), 'Main spring lot (picnic area & swim lawn)', 28.7118, -81.4622, 'Included in park entry ($6 per vehicle, paid online with the reservation)', null, null, false, 'curated', 'Approximate location west of the spring lawn, near 1800 Wekiwa Circle. Entry is by day-use reservation only, so the lot rarely overflows but reservations sell out on hot weekends. ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'wekiwa-springs-state-park'), 'Overflow lot along the park drive', 28.7108, -81.4642, 'Included in park entry', null, null, true, 'curated', 'Approximate location. Grass/overflow parking opened by rangers on peak days; longer walk to the spring.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'madison-blue-spring-state-park'), 'Day-use lot at the spring', 30.4807, -83.2446, 'Included in park entry ($5 per vehicle for 2-8 people, $4 single-occupant); pay by QR code at the entrance', null, null, false, 'curated', 'Approximate location near 8300 N.E. State Road 6, Lee. Official notice: the park closes frequently between 10 a.m. and 3 p.m. on weekends and holidays when it reaches capacity, and may reopen later the same day. Visitors may not park and wait on the roadside or in the entrance area - local law enforcement issues citations. Large RVs, RVs pulling trailers and truck-camper combinations are not recommended (limited turnaround space). ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'lafayette-blue-springs-state-park'), 'North entrance day-use lot (spring)', 30.1255, -83.227, 'Included in park entry ($5 per vehicle, honor box - correct change required)', null, null, false, 'curated', 'Approximate location near 799 N.W. Blue Spring Road, Mayo. Official: paved parking for day visitors in the day-use area, plus two bus/trailer spots; the boat ramp at the south entrance has over-sized parking for six vehicles. No reservations and no published capacity-closure pattern. ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'troy-spring-state-park'), 'Day-use lot above the spring', 30.0052, -82.99824, 'Included in park entry ($5 per vehicle, honor box - correct change required)', null, null, false, 'curated', 'OSM parking way 203171979 (fee=yes) near 674 N.E. Troy Springs Road, Branford. A long, paved switchback ramp runs from the parking area down to the spring dock; divers often use a wagon to carry gear. Small park with no published capacity-closure pattern. ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'fanning-springs-state-park'), 'Main day-use lot (spring and picnic area)', 29.5889, -82.934, 'Included in park entry ($6 per vehicle); $2 per person arriving by boat (honor box on the dock)', null, null, false, 'curated', 'Approximate location near 18020 N.W. Highway 19, off US 19/98 at the Suwannee River bridge. First-come, first-served with no reservations and no published capacity-closure pattern. Effective Aug. 20, 2026 the floating dock is under an improvement project. ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'manatee-springs-state-park'), 'Main day-use lot (spring and boardwalk)', 29.48746, -82.97723, 'Included in park entry ($6 per vehicle)', 150, null, false, 'curated', 'OSM parking multipolygon 9848435 (paved, capacity=150 per OSM - unverified by the park) near 11650 N.W. 115 St., Chiefland. An 800-ft boardwalk leads from the day-use area to the spring. The waterfront restroom has been closed since Jan. 14, 2026 and no EV charging is allowed in the park. ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'de-leon-springs-state-park'), 'Main lot (spring, pancake house and visitor center)', 29.13243, -81.36287, 'Included in park entry ($6 per vehicle)', null, null, false, 'curated', 'OSM parking node 3240587929 near 601 Ponce De Leon Blvd. Official: accessible parking is available near all facilities, with sidewalks and boardwalks to the spring (count of ADA spaces not published). No day-use reservations; visitor reviews report the park reaching capacity on hot weekends. Expect a wait for the Old Sugar Mill Pancake House.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'weeki-wachee-springs-state-park'), 'Main paid lot at the park entrance', 28.51646, -82.57486, 'Included in per-person admission ($13 adults, $8 children 6-12)', null, 10, false, 'curated', 'OSM parking way 1148344196 (paved) at 6131 Commercial Way, US 19 at SR 50. Large paved lot run by concessionaire Guest Services; the official accessibility page lists 10 accessible spaces about 20 yards from the entrance (OSM tags 14). Admission is per person at the gate - once the park reaches capacity no more tickets are sold for the rest of the day, and you may not re-enter while it is full.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'kelly-park-rock-springs'), 'Main lot inside the entrance gate', 28.756, -81.4955, '$5 per vehicle, $10 per bus (effective Aug. 11, 2026); cash or Visa/MasterCard/Discover with photo ID', 280, null, false, 'curated', 'Approximate location near the gatehouse at 400 E. Kelly Park Rd, Apopka. Official: 280 vehicles are admitted each morning and the gate closes when the park is full - typically within an hour of opening on a summer day. Once full, the first 50 cars in line get an afternoon parking pass (one per car) for the 1 p.m. re-opening, for about 330 vehicles and 1,350 visitors a day. Check the county web page or the capacity information line (407-254-1906), which are updated when the park is full. Leaving temporarily requires a re-entry stamp from the gatehouse. ADA space count not published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'hart-springs-park'), 'Day-use lot (springs entrance)', 29.6762, -82.9508, 'Included in the per-person day-use fee ($5 weekday / $8 weekend and holidays April-September, $3 October-March)', null, null, false, 'curated', 'Approximate location just east of the spring, off the entrance drive from 4240 SW 86th Avenue - this lot is not mapped in OpenStreetMap. Pay at the staffed booth on the way in. The park sets a daily capacity and stops admitting new visitors once it is reached, so a shelter or Pavilion A/B reservation is the only guaranteed way in on a hot weekend. Accessible parking is reported by third-party guides but the county publishes no ADA space count.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'hart-springs-park'), 'Boat ramp parking (Suwannee River)', 29.67424, -82.95443, 'Included in the day-use fee', null, null, false, 'curated', 'At the Hart Springs boat ramp on the Suwannee River (OSM slipway node 3666202908), a short walk downstream of the swimming area. Trailer parking, so it fills on good river days and is not a substitute for the day-use lot.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'lithia-springs-conservation-park'), 'Spring swim-area lot (north)', 27.8665, -82.23004, 'Included in the $2 per-vehicle entrance fee; the $2 per-person swim band is bought separately at the gate', null, null, false, 'curated', 'OSM parking way 312352096, the lot closest to the fenced swimming area. Parking spaces are first come, first served. Because each four-hour swim slot is capped at 200 swimmers, this lot turns over at the 1 p.m./2 p.m. changeover rather than filling for the whole day.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'lithia-springs-conservation-park'), 'Spring swim-area lot (south)', 27.86637, -82.23026, 'Included in the $2 per-vehicle entrance fee', null, null, false, 'curated', 'OSM parking way 312352097, the second lot at the swimming area. First come, first served; no ADA space count is published.');
insert into public.parking_lots ("park_id", "name", "lat", "lng", "fee", "capacity", "ada_spaces", "is_overflow", "source", "notes")
values ((select id from public.parks where slug = 'lithia-springs-conservation-park'), 'Paved lot near the park entrance', 27.86591, -82.22912, 'Included in the $2 per-vehicle entrance fee', null, null, true, 'curated', 'OSM parking way 415385722, an asphalt lot about 150 m east of the swim area toward the entrance station and campground. Useful when the two swim-area lots are full; it is a longer walk to the spring over natural surface.');

-- ---------------------------------------------------------------- park_alerts (manual)
delete from public.park_alerts where source = 'manual' and park_id in (select id from public.parks where slug in ('gilchrist-blue-springs-state-park', 'poe-springs-park', 'ichetucknee-springs-state-park', 'rainbow-springs-state-park', 'wekiwa-springs-state-park', 'madison-blue-spring-state-park', 'fanning-springs-state-park', 'manatee-springs-state-park', 'weeki-wachee-springs-state-park', 'kelly-park-rock-springs', 'lithia-springs-conservation-park', 'cypress-spring'));
insert into public.park_alerts ("park_id", "kind", "text", "source", "official_url", "severity", "starts_at", "ends_at", "hash", "first_seen", "last_seen", "active", "last_checked_at")
values ((select id from public.parks where slug = 'gilchrist-blue-springs-state-park'), 'closure', 'Effective Oct. 29, 2025: Due to construction renovations, there are no water activities available at Ruth B. Kirby Gilchrist Blue Springs State Park. The large pavilion, large picnic area and volleyball courts are open; port-o-let facilities are in place until renovations are complete. Rentals and concession services are also unavailable. No reopening date has been announced.', 'manual', 'https://www.floridastateparks.org/learn/construction-renovations-ruth-b-kirby-gilchrist-blue-springs-state-park', 'Severe', '2025-10-29T00:00:00-04:00'::timestamptz, null, '59e9149d2f98694b82679765f3183e64d9dbcdba', now(), now(), true, now())
on conflict ("hash") do update set "text" = excluded."text", "official_url" = excluded."official_url", "severity" = excluded."severity", "starts_at" = excluded."starts_at", "ends_at" = excluded."ends_at", "active" = excluded."active", "last_seen" = now(), "last_checked_at" = now();
insert into public.park_alerts ("park_id", "kind", "text", "source", "official_url", "severity", "starts_at", "ends_at", "hash", "first_seen", "last_seen", "active", "last_checked_at")
values ((select id from public.parks where slug = 'poe-springs-park'), 'closure', 'Effective Thursday, July 16, 2026: The designated swimming area at Poe Springs Park is temporarily closed due to poor water clarity, and is reassessed weekly. The rest of the park (picnic areas, trails, boat launch and paddling) remains open. In August 2026 the Florida Springs Institute reported that the spring had stopped flowing during drought; no reopening timeline has been given.', 'manual', 'https://alachuacounty.us/Depts/Parks/Pages/Details.aspx?park=Poe+Springs+Park', 'Severe', '2026-07-16T00:00:00-04:00'::timestamptz, null, '0f571fbf066d52163828bb2e9cd3621d65cc2f1f', now(), now(), true, now())
on conflict ("hash") do update set "text" = excluded."text", "official_url" = excluded."official_url", "severity" = excluded."severity", "starts_at" = excluded."starts_at", "ends_at" = excluded."ends_at", "active" = excluded."active", "last_seen" = now(), "last_checked_at" = now();
insert into public.park_alerts ("park_id", "kind", "text", "source", "official_url", "severity", "starts_at", "ends_at", "hash", "first_seen", "last_seen", "active", "last_checked_at")
values ((select id from public.parks where slug = 'ichetucknee-springs-state-park'), 'notice', 'Effective March 17, 2026: The Midpoint Tube Launch is closed until further notice for repairs. Tubers can continue to launch from Dampier''s Landing at the South Entrance until 5 p.m. Tube rentals end at 4:30 p.m.', 'manual', 'https://www.floridastateparks.org/parks-and-trails/ichetucknee-springs-state-park', 'Moderate', '2026-03-17T00:00:00-04:00'::timestamptz, null, '8b5d1de3c8c81f7ad59a21e93d6d6c07ed086a88', now(), now(), true, now())
on conflict ("hash") do update set "text" = excluded."text", "official_url" = excluded."official_url", "severity" = excluded."severity", "starts_at" = excluded."starts_at", "ends_at" = excluded."ends_at", "active" = excluded."active", "last_seen" = now(), "last_checked_at" = now();
