values ((select id from public.parks where slug = 'ichetucknee-springs-state-park'), 'notice', 'Effective May 20, 2026: Expect high visitation on weekends and holidays. When the park reaches capacity it temporarily closes to all visitors, including those with rental reservations or digital day passes. Entry is first-come, first-served; visitors may not park and wait on the roadside, and local law enforcement will issue citations.', 'manual', 'https://www.floridastateparks.org/parks-and-trails/ichetucknee-springs-state-park/hours-fees', 'Moderate', '2026-05-20T00:00:00-04:00'::timestamptz, null, '4b2e8f28d5087c453ca7ec07476debc71a6d3b3d', now(), now(), true, now())
