values ((select id from public.parks where slug = 'wekiwa-springs-state-park'), 'notice', 'Effective Sept. 2, 2025: Reservations are required for day-use entry to Wekiwa Springs State Park for all visitors, including annual passholders. Reservations open 60 days ahead; same-day reservations are available until the daily limit is met.', 'manual', 'https://www.floridastateparks.org/learn/day-use-entry-reservation-pilot-program-information', 'Minor', '2025-09-02T00:00:00-04:00'::timestamptz, null, 'a4fac950dd3ed5ba197891a6cc1f3e9d9742d804', now(), now(), true, now())
