values ((select id from public.parks where slug = 'madison-blue-spring-state-park'), 'notice', 'Park capacity information: Madison Blue Spring State Park experiences frequent closures between 10 a.m. and 3 p.m. on weekends and holidays due to high visitation. The park closes when it reaches capacity but may reopen to additional visitors later that day. For their safety, visitors are not permitted to park and wait in their cars on the side of the road or in the park entrance area; local law enforcement will issue citations.', 'manual', 'https://www.floridastateparks.org/parks-and-trails/madison-blue-spring-state-park', 'Moderate', '2026-05-01T00:00:00-04:00'::timestamptz, null, 'daebb7c11c8021697a437a0caf323d498cd3036f', now(), now(), true, now())
