values ((select id from public.parks where slug = 'madison-blue-spring-state-park'), 'notice', 'Effective April 2, 2026: Large RVs, RVs pulling trailers or truck and camper combinations are not recommended at Madison Blue Spring State Park due to limited turnaround space.', 'manual', 'https://www.floridastateparks.org/parks-and-trails/madison-blue-spring-state-park', 'Minor', '2026-04-02T00:00:00-04:00'::timestamptz, null, '0ef062ed8e6ba7269f61e22b4c44283d8ad63e7c', now(), now(), true, now())
