values ((select id from public.parks where slug = 'fanning-springs-state-park'), 'notice', 'Effective Aug. 20, 2026: The floating dock at Fanning Springs State Park will be undergoing an improvement project. Until further notice, swimming and boating will remain open but be prepared to be asked to exit at all times for safety purposes.', 'manual', 'https://www.floridastateparks.org/parks-and-trails/fanning-springs-state-park', 'Moderate', '2026-08-20T00:00:00-04:00'::timestamptz, null, '9b2bad557003dab7775fdbda2b8d85e32e40ffd5', now(), now(), true, now())
