values ((select id from public.parks where slug = 'manatee-springs-state-park'), 'notice', 'Effective Jan. 14, 2026: The waterfront restroom and dump station at Manatee Springs State Park are currently closed. There is no electric vehicle charging allowed in the park. ADA restrooms and showers remain open in the Magnolia 1 and Hickory camping loops.', 'manual', 'https://www.floridastateparks.org/parks-and-trails/manatee-springs-state-park', 'Moderate', '2026-01-14T00:00:00-05:00'::timestamptz, null, 'a8f59afe8221a9cdd9d35d40e9a8cf1d76974664', now(), now(), true, now())
