values ((select id from public.parks where slug = 'weeki-wachee-springs-state-park'), 'notice', 'Effective Dec. 12, 2025: Due to low water levels, the Wilderness River Cruise at Weeki Wachee Springs State Park is paused during daytime hours. The mermaid shows, Ranger Experience and Buccaneer Bay beach and swimming are unaffected.', 'manual', 'https://www.floridastateparks.org/WeekiWachee', 'Minor', '2025-12-12T00:00:00-05:00'::timestamptz, null, '03b83935b993e1ca0c087eec46b19fea72104170', now(), now(), true, now())
