values ((select id from public.parks where slug = 'weeki-wachee-springs-state-park'), 'notice', 'Buccaneer Bay schedule: the beach and swimming are open daily, but the water slides and lazy river run on Saturdays and Sundays only from Aug. 11 to Sept. 27, 2026 and are closed for the season beginning Sept. 28, 2026. The kiddie pool is closed for renovations. Once the park is full, no more tickets are sold and you cannot re-enter.', 'manual', 'https://www.floridastateparks.org/frequently-asked-questions', 'Minor', '2026-08-11T00:00:00-04:00'::timestamptz, null, '8e485e72d5269928d2c8bdc35152ae2b75370839', now(), now(), true, now())
