values ((select id from public.parks where slug = 'kelly-park-rock-springs'), 'notice', 'Park capacity: each morning 280 vehicles are allowed into Kelly Park, and an additional 50 vehicles are admitted after 1 p.m. with an afternoon parking pass - about 330 vehicles and an average of 1,350 visitors a day. On a typical summer day the park fills within an hour of opening. You must collect a pass in the morning when the park first hits capacity to get in at the 1 p.m. re-opening (one pass per car, first-come, first-served). The county web page and the information line, 407-254-1906, are updated when the park is full.', 'manual', 'https://www.ocfl.net/cultureparks/parks.aspx?d=22&m=dtlvw', 'Moderate', '2026-08-11T00:00:00-04:00'::timestamptz, null, '2851f24bc3a105e5cef9c2ff19156ecef1cda46d', now(), now(), true, now())
