values ((select id from public.parks where slug = 'lithia-springs-conservation-park'), 'closure', 'Hillsborough County announcement: "Due to high water levels and unsafe conditions, the spring is currently closed for swimming." The rest of Lithia Springs Conservation Park - campground, trails, playground and picnic areas - remains open. No reopening date has been given; the county page was last updated 10 September 2026.', 'manual', 'https://hcfl.gov/locations/lithia-springs-park', 'Severe', '2026-09-10T00:00:00-04:00'::timestamptz, null, '11fe5cfb67b878780ea34ebb90288d450c4b930e', now(), now(), true, now())
