values ((select id from public.parks where slug = 'cypress-spring'), 'notice', 'Northwest Florida Water Management District, 8 January 2026: contractors have begun the Cypress Spring shoreline restoration and protection project, adding shoreline stabilisation, boardwalks and steps at the entry and exit points. While the work continues, access to the shoreline may be restricted; the spring itself remains accessible by watercraft. The District said the work was expected to last several months and has not posted a completion notice.', 'manual', 'https://nwfwater.com/restoration-work-begins-at-cypress-spring/', 'Minor', '2026-01-08T00:00:00-05:00'::timestamptz, null, '94087eaa1ca0f61c208b335c70f67fe3f1358813', now(), now(), true, now())
