-- ---------------------------------------------------------------- reviews (is_sample = true)
delete from public.reviews where is_sample = true;
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'ichetucknee-springs-state-park'), 5, 'Tubed the full run on a Tuesday and it was close to empty. Water is genuinely cold, about 72, so give yourself a minute before pushing off. The tram back was running every 20 minutes.', '675f8c0d-3cdb-45ed-8ff2-a2d01773d0ee'::uuid, true, now() - interval '6 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'ichetucknee-springs-state-park'), 4, 'Beautiful, but the north entrance had already closed to new cars by 10 on a Saturday. Went to the south entrance instead and got in with no wait.', '62820d45-9d3c-49da-8e02-0364e8e8a3ce'::uuid, true, now() - interval '13 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'ichetucknee-springs-state-park'), 5, 'Clearest water I have swum in. Bring water shoes for the limestone and do not underestimate how far the tube run is with small children.', '2210999c-e94b-4149-8479-0203e2400061'::uuid, true, now() - interval '21 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'ichetucknee-springs-state-park'), 3, 'Lovely spring, but we queued 40 minutes at the gate and the lot filled before we reached the front. Go early or go midweek.', 'ba01dbbc-596c-4a97-822f-6cb12e8b8f4d'::uuid, true, now() - interval '32 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'rainbow-springs-state-park'), 5, 'The headspring basin is enormous and the gardens are worth the walk on their own. Reservation for the head springs entrance was quick to book the night before.', 'c64703a0-71bf-432e-83d7-4f5b26f679f5'::uuid, true, now() - interval '4 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'rainbow-springs-state-park'), 4, 'Swim area is roped and shallow at the edge, good for children. Concession tube rental ran out by midday.', '3bcd6343-afe4-4515-893b-47b9bfa6f918'::uuid, true, now() - interval '11 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'rainbow-springs-state-park'), 4, 'Busy but well managed. Plenty of shade near the picnic area, which matters in August.', '754c18cc-437a-4f51-8527-2be9ef1eb0a5'::uuid, true, now() - interval '25 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'blue-spring-state-park'), 5, 'Went in September so swimming was open. In winter the manatees take over and the water closes, so check before you drive.', '8c89143f-d956-4138-8f14-4ae399587dc3'::uuid, true, now() - interval '8 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'blue-spring-state-park'), 4, 'Boardwalk along the run is the best part. Parking filled by 10:30 and they were turning cars away at the gate.', '8b62e75e-1d7d-4f3f-8196-7f0bc281a581'::uuid, true, now() - interval '17 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'blue-spring-state-park'), 5, 'Swam the run from the boil down to the dock. Cold, clear and deep in the middle.', 'dadf7873-f4c7-4dc1-80ae-bbc259e634f7'::uuid, true, now() - interval '29 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'wekiwa-springs-state-park'), 4, 'Easy drive from Orlando which is exactly why it fills early. Swim area is concrete edged and shallow, more of a pool than a wild spring.', '3566e848-dac4-4e20-81f8-1c0ea4b8e72a'::uuid, true, now() - interval '5 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'wekiwa-springs-state-park'), 3, 'Arrived at 11 on a Sunday and the park was already at capacity. Came back at 3 and got straight in.', 'f42872e7-e3d1-47b4-82c5-903235477ffe'::uuid, true, now() - interval '15 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'wekiwa-springs-state-park'), 5, 'Rented a canoe and paddled up the run. Saw two otters. Worth doing before you swim.', '6c33b5df-5449-471f-8991-ec77f86ef110'::uuid, true, now() - interval '27 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'ginnie-springs'), 4, 'Private park so the rules are different: alcohol is allowed and it gets loud on summer weekends. Water is spectacular and the diving is the real draw.', '13fb3b7e-626a-4612-89cc-f7f5414fd639'::uuid, true, now() - interval '9 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'ginnie-springs'), 2, 'Went on a holiday weekend and it was closer to a festival than a spring. Beautiful water, but not what we wanted with young children.', '77292d46-4a59-428e-89fe-c2878078cd54'::uuid, true, now() - interval '19 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'ginnie-springs'), 5, 'Midweek in the shoulder season it is close to perfect. Camped overnight and had the Devil''s Eye area almost to ourselves at dawn.', '1ac2afcb-0286-4a36-8753-55de350e8bdb'::uuid, true, now() - interval '34 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'de-leon-springs-state-park'), 5, 'The pancake house is the reason half the queue exists. Spring itself is a walled basin, very easy to get in and out of.', '3a1f47df-2580-49d9-82f3-6537e2623875'::uuid, true, now() - interval '7 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'de-leon-springs-state-park'), 4, 'Swim area was open and clear. Put your name down for a griddle table before you swim, the wait runs over an hour.', '7eb5ed7f-cb2f-4350-8838-8b10175307ce'::uuid, true, now() - interval '22 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'manatee-springs-state-park'), 4, 'Boardwalk out to the Suwannee is lovely and the spring run is shallow enough to wade. Vultures everywhere, which is stranger than it sounds.', '89673469-9abe-4a95-8caa-52cd9eaa0f93'::uuid, true, now() - interval '12 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'manatee-springs-state-park'), 3, 'River was high after rain so the spring was tea coloured. Staff were upfront about it at the gate.', '1d1de7ec-ec64-46c4-8f13-3a9a62aa6fb6'::uuid, true, now() - interval '26 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'kelly-park-rock-springs'), 5, 'Floating the run at Rock Springs is the best hour you can have for a few dollars. Get a reservation, they sell out days ahead in summer.', '6edeaaef-8b3b-4646-840c-9c5bd568a840'::uuid, true, now() - interval '10 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'kelly-park-rock-springs'), 4, 'Arrived without a reservation on a Thursday and still got in at 9:15. By 10 the lot was full.', 'd6404de9-34e4-469c-8b15-4d2d27e8157d'::uuid, true, now() - interval '20 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'madison-blue-spring-state-park'), 5, 'Small, quiet and gorgeous. Capacity is genuinely limited so they close the gate early on weekends.', 'ddfcef16-f4b0-43fa-8660-6b80297b117c'::uuid, true, now() - interval '14 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'gilchrist-blue-springs-state-park'), 4, 'One of the newer state parks and it shows, facilities are tidy. Short walk from the lot to the water.', 'a39fbacc-7a00-4c14-8e48-50fdad5218f1'::uuid, true, now() - interval '18 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'fanning-springs-state-park'), 3, 'Pleasant stop rather than a destination. The spring is small and the river was murky when we went.', '60e3f7b3-e3c9-4665-8802-4eeb0a4773cf'::uuid, true, now() - interval '16 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'troy-spring-state-park'), 4, 'Steep steps down to the spring and no lifeguard. The sunken steamboat is visible from the bank when the water is clear.', '5d7ba4d4-b0c8-4416-8858-73d6c563cd6a'::uuid, true, now() - interval '23 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'lafayette-blue-springs-state-park'), 4, 'Natural limestone bridge over the spring is unusual and worth seeing. Very quiet midweek.', 'a27805b4-85b8-4e53-8907-eaa8e3f339e4'::uuid, true, now() - interval '28 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'poe-springs-park'), 3, 'Was closed for swimming when we visited. The boardwalk and picnic area were still open and pleasant.', 'd416f559-999f-4306-8e7e-688e40259303'::uuid, true, now() - interval '30 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'weeki-wachee-springs-state-park'), 4, 'Buccaneer Bay is a water park attached to a spring, so expect slides and crowds rather than wilderness. Children loved it.', 'd134103b-20db-455e-8260-b4e5d52b9fc1'::uuid, true, now() - interval '3 days');
insert into public.reviews ("park_id", "rating", "body", "device_id", "is_sample", "created_at")
values ((select id from public.parks where slug = 'weeki-wachee-springs-state-park'), 3, 'Reached capacity before 10 on a Saturday and they close the whole park, not just the water. The mermaid show is genuinely charming.', '504dc8d0-b99c-494b-873f-306234de22cb'::uuid, true, now() - interval '24 days');

